/// How long after the last repaint blink (`Terminal::repaint_blink_epoch`: a
/// DECTCEM hide inside a DEC-2026 update, as Claude Code brackets each
/// keystroke's repaint) the alt-screen erase-poof row probe stays enabled. Spans
/// a kill press in a lull between repaints, and shuts off promptly when a
/// non-blinking alt-screen app (vim, less) takes over. Shared with the headless
/// capture path (`app_introspect`).
pub(crate) const BLINK_RECENT_MAX: Duration = Duration::from_secs(1);

/// Resolve one captured frame's row-probe
/// [`aterm_effects::cursor_glow::ProbeTrust`]. The probe is always available
/// (content seams need it on `less` search, `vi` insert mode and TUIs writing
/// elsewhere via ESC 7/ESC 8), but plain alt-screen apps get `ContentOnly`
/// trust: page scrolls and region scrolls slide content through the cursor row,
/// so every kill/poof branch in the engine refuses `ContentOnly`. All four
/// capture seams (single-pane hold, composed live/headless seam, split compose,
/// headless `app_introspect`) resolve trust here.
pub(crate) fn row_probe_trust(
    is_alt: bool,
    blink_recent: bool,
) -> aterm_effects::cursor_glow::ProbeTrust {
    if !is_alt || blink_recent {
        aterm_effects::cursor_glow::ProbeTrust::Full
    } else {
        aterm_effects::cursor_glow::ProbeTrust::ContentOnly
    }
}

/// Whether ordinary forward-typing momentum is allowed to own the cursor cat.
///
/// The trail master owns the kitty companion just as surely as it owns the
/// ribbon behind it.  Collection/typed hellos deliberately do not use this
/// predicate: they are bounded, independently promised presentations and the
/// host ORs `collection_hello` around this ordinary-flight gate.
#[inline]
pub(crate) fn ordinary_kitty_cursor_enabled(
    cursor_trail_enabled: bool,
    style: crate::cursor_glow::GlowStyle,
) -> bool {
    cursor_trail_enabled && matches!(style, crate::cursor_glow::GlowStyle::RainbowKitty)
}

/// Consume one echo-correlated cursor pulse and forward it only when the rainbow kitty
/// companion's trail owner is enabled. The pulse is consumed even while gated
/// off so toggling the owner cannot replay stale typing.
#[inline]
pub(crate) fn forward_kitty_cursor_motion(
    cursor_trail_enabled: bool,
    pet_mode: bool,
    style: crate::cursor_glow::GlowStyle,
    pulse: Option<aterm_effects::cursor_glow::CursorCatMotionPulse>,
    cat: &mut crate::kitty_cursor::CursorCat,
) {
    if ordinary_kitty_cursor_enabled(cursor_trail_enabled, style)
        && let Some(pulse) = pulse
    {
        if pet_mode {
            cat.on_pet_mode_motion_pulse(pulse);
        } else {
            cat.on_motion_pulse(pulse);
        }
    }
}

/// Ground an ordinary flying episode as soon as its trail owner goes away (hot
/// reload disabling the master or switching styles), so an invisible sprite's
/// fade/bob state buys no frame cadence. Pet mode has the same rule while the
/// resident owns idle glass. `retire_unowned_cursor_motion` keeps a hidden
/// tenure and explicit collection/song promises.
#[inline]
pub(crate) fn retire_kitty_cursor_without_owner(
    cursor_trail_enabled: bool,
    pet_mode: bool,
    style: crate::cursor_glow::GlowStyle,
    sing_drive: f32,
    cat: &mut crate::kitty_cursor::CursorCat,
) {
    if !ordinary_kitty_cursor_enabled(cursor_trail_enabled, style)
        || (pet_mode && sing_drive <= 0.0)
    {
        cat.retire_unowned_cursor_motion();
    }
}

/// Exact host presentation gate shared by glass and styled captures. A
/// collection hello bypasses both the ordinary trail owner and the animation
/// requirement; an ordinary flight must satisfy both.
#[inline]
pub(crate) fn cursor_cat_presentation_enabled(
    animate_cat: bool,
    cursor_trail_enabled: bool,
    style: crate::cursor_glow::GlowStyle,
    collection_hello: bool,
) -> bool {
    collection_hello || (animate_cat && ordinary_kitty_cursor_enabled(cursor_trail_enabled, style))
}

/// The flying head's live drawn rect in grid pixels `(x0, x1, y0, y1)`, for
/// the ambient word-cats' pixel yield.
///
/// Pure and cheap: [`crate::word_decorations::WordDecorations::kitty_cursor_footprint`]
/// takes `&self`, latches nothing, and is exactly what the emitter's own
/// placement is debug-asserted to equal — so this may be called before the
/// word tick, which is where the yield box is needed and hours before the
/// placement is resolved.
pub(crate) fn flying_head_footprint_px(
    word_decos: &crate::word_decorations::WordDecorations,
    geom: crate::word_decorations::EffectGeom,
    cell: (u16, u16),
    look: aterm_effects::kitty_registry::KittyLook,
    bob: f32,
) -> Option<(i32, i32, i32, i32)> {
    let fp = word_decos.kitty_cursor_footprint(crate::word_decorations::KittyCursorLayout {
        geom,
        cursor: cell,
        look,
        bob,
    })?;
    Some((fp.x, fp.x + i32::from(fp.w), fp.y, fp.y + i32::from(fp.h)))
}

/// Reserve host glyphs that will be spliced after the console observation.
/// Pure geometry: prediction expiry/reconciliation remains on its existing
/// paint path. The current find match is already a terminal selection; both
/// possible find-bar bands are reserved because its late placement can flip.
pub(crate) fn pet_console_exclusions(
    input: &aterm_core::render::RenderInput,
    preedit: bool,
    predictions: Option<(usize, usize, usize, usize)>,
    find_open: bool,
) -> ([aterm_effects::pet_world::PetRect; 4], usize) {
    use aterm_effects::pet_world::PetRect;
    let mut rects = [PetRect::default(); 4];
    let mut count = 0;
    if preedit && input.display_offset == 0 && input.cursor_row < input.rows && input.cols > 0 {
        rects[count] = PetRect::new(input.cursor_row as f32, 0.0, 1.0, input.cols as f32);
        count += 1;
    }
    if input.display_offset == 0
        && let Some((r0, c0, r1, c1)) = predictions
    {
        let r1 = r1.min(input.rows);
        let c1 = c1.min(input.cols);
        if r0 < r1 && c0 < c1 {
            rects[count] = PetRect::new(r0 as f32, c0 as f32, (r1 - r0) as f32, (c1 - c0) as f32);
            count += 1;
        }
    }
    if find_open && input.rows > 0 && input.cols > 0 {
        let rows = crate::find_bar::FIND_BAR_ROWS.min(input.rows);
        rects[count] = PetRect::new(0.0, 0.0, rows as f32, input.cols as f32);
        rects[count + 1] = PetRect::new(
            (input.rows - rows) as f32,
            0.0,
            rows as f32,
            input.cols as f32,
        );
        count += 2;
    }
    (rects, count)
}

#[cfg(test)]
mod pet_console_observation_tests {
    use super::pet_console_exclusions;
    use aterm_core::terminal::Terminal;
    use aterm_effects::pet_world::{PetPane, PetRect, PetWorld, PetWorldFacts};

    #[test]
    fn late_native_overlays_reserve_real_cells_before_pet_planning() {
        let mut term = Terminal::new(20, 60);
        term.process(b"\x1b]11;#000000\x07\x1b[6;20H");
        let input = term.cell_frame(20, 60);
        let facts = PetWorldFacts::read(&term, 7);
        let (exclusions, count) = pet_console_exclusions(&input, true, Some((7, 3, 9, 12)), true);
        assert_eq!(count, 4);
        let mut world = PetWorld::default();
        assert!(world.observe_with_exclusions(
            &input,
            &facts,
            PetPane::full(&input),
            &exclusions[..count]
        ));
        for (row, col) in [(5.0, 40.0), (7.0, 6.0), (0.0, 40.0), (19.0, 40.0)] {
            assert!(!world.clear(PetRect::new(row, col, 1.0, 1.0), 0.0));
        }
        assert!(world.clear(PetRect::new(12.0, 40.0, 2.0, 6.0), 0.2));
        let (_, none) = pet_console_exclusions(&input, false, None, false);
        assert_eq!(none, 0);
    }

    #[test]
    fn history_never_projects_pending_live_input_onto_old_rows() {
        let mut term = Terminal::new(10, 40);
        for _ in 0..15 {
            term.process(b"line\r\n");
        }
        term.scroll_display(3);
        let input = term.cell_frame(10, 40);
        assert_ne!(input.display_offset, 0);
        let (_, count) = pet_console_exclusions(&input, true, Some((3, 4, 4, 5)), false);
        assert_eq!(count, 0);
    }
}

