/// A failed command (`exit 1`, `dur_ms` of runtime) finishing in the pet's
/// session, through the owner's completion latch: a baseline frame, then the
/// completion. Returns what the grief gate reads between the notes and the
/// tick.
#[cfg(test)]
pub(crate) fn pet_fails_a_command_for_test(
    ws: &mut WindowState,
    now: Instant,
    dur_ms: Option<u64>,
) -> bool {
    let baseline = pet_prepare_for_test(ws, now, 0, None, None);
    let _ = ws.fx.companion_mut().tick(baseline);
    let failed = pet_prepare_for_test(ws, now, 0, None, Some((1, 1, dur_ms)));
    let grieving = ws.fx.companion_mut().grieving();
    let _ = ws.fx.companion_mut().tick(failed);
    grieving
}

/// Drive the real resident brain into a live far-caret arc for present/capture
/// regression fixtures. Test-only: production has no synthetic pet controls.
#[cfg(test)]
pub(crate) fn seed_resident_pet_mid_flight_for_test(
    ws: &mut WindowState,
    start: Instant,
    rows: u16,
    cols: u16,
    cell_w: u16,
    cell_h: u16,
    target: (u16, u16),
) -> (Instant, aterm_effects::kitty_pet::PetFrame) {
    use aterm_effects::host::CaptureMode;
    let sense = |now, caret| aterm_effects::kitty_pet::PetSense {
        caret_drawn: true,
        now,
        caret,
        rows,
        cols,
        cell_w,
        cell_h,
        reduced_motion: false,
        output_burst: false,
        pointer: None,
        wrapped: false,
    };
    ws.fx.companion_mut().drain();
    let first = pet_tick_for_test(ws, CaptureMode::StaticCapture, sense(start, Some((2, 2))));
    assert!(first.alpha > 0, "fixture materializes the resident");

    let mut now = start;
    for caret in [(2, 3), (2, 4)] {
        now += Duration::from_millis(50);
        let _ = pet_tick_for_test(ws, CaptureMode::Present, sense(now, Some(caret)));
    }
    for _ in 0..120 {
        now += Duration::from_millis(16);
        let _ = pet_tick_for_test(ws, CaptureMode::Present, sense(now, Some((2, 4))));
    }
    for _ in 0..180 {
        now += Duration::from_millis(16);
        let frame = pet_tick_for_test(ws, CaptureMode::Present, sense(now, Some(target)));
        if frame.action == aterm_effects::kitty_pet::PetAction::Leap && frame.lift > 0.0 {
            return (now, frame);
        }
    }
    panic!("fixture failed to earn a resident-pet flight");
}

/// WHICH rendered-cell snapshot the v2 companion router probes for ink: the
/// single-pane present (and both capture splices) read the window's
/// `input_scratch`; the composed path reads the focused pane's own
/// `composed_focus_scratch`, at pane geometry.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum CompanionInk {
    /// `WindowState::input_scratch` — the whole grid.
    Single,
    /// `WindowState::composed_focus_scratch` — the focused pane.
    Composed,
}

impl CompanionInk {
    /// The pipeline sprite channel a companion drawn for this snapshot lands
    /// in: the window's for the whole grid, the pane staging one (placed
    /// into the window by the pane's placement) for the focused pane.
    fn canvas(self) -> aterm_effects::pipeline::CanvasInk {
        match self {
            Self::Single => aterm_effects::pipeline::CanvasInk::Window,
            Self::Composed => aterm_effects::pipeline::CanvasInk::Pane,
        }
    }
}

/// THE COMPANION SEAM (`docs/design/RAINBOW-KITTY-V2.md` §7.2, D13): the
/// flying head's route, which both render arms call before either body is
/// drawn — [`emit_single_cursor_companion`] (the live present and both
/// capture splices) and `App::compose_cursor_companion` (the split path).
/// The law is the engine's
/// ([`aterm_effects::pipeline::EffectsPipeline::route_flying_head`]); this
/// host names the snapshot the seat law probes for ink and whether the head
/// `animate`s this frame (the motion policy's verdict: a still head takes the
/// teleport and none of the meteor's beats).
pub(crate) fn route_v2_companion(
    ws: &mut WindowState,
    ink: CompanionInk,
    duty: CompanionDuty,
    now: Instant,
    geom: aterm_effects::word_decorations::EffectGeom,
    cat_frame: &mut crate::kitty_cursor::CatFrame,
    animate: bool,
) {
    let cells: &[Vec<RenderCell>] = match ink {
        CompanionInk::Single => &ws.input_scratch.cells,
        CompanionInk::Composed => &ws.composed_focus_scratch.cells,
    };
    ws.fx
        .route_flying_head(duty, cells, now, geom, cat_frame, animate);
}

