mod v2_companion_router_tests;

/// Emit the cursor-owned companion sprites for a single-grid frame.
///
/// `WordDecorations` supplies the shared atlas and bakers, but Sparkle Words
/// does not own this lifecycle. Keeping the emission in a config-free helper
/// lets the live renderer and explicit capture both draw the resident pet or
/// authenticated flying kitty when `[sparkle_words]` is disabled.
///
/// `present` says whether this emission is a drawn present (`redraw_window`)
/// or a capture splice re-using the emitter (`app_introspect`, both arms):
/// only a present may spend a hello — see [`emit_resident_pet`].
#[allow(
    clippy::too_many_arguments,
    reason = "one resolved companion frame carries geometry, palette, motion and custody inputs"
)]
pub(crate) fn emit_single_cursor_companion(
    ws: &mut WindowState,
    geom: crate::word_decorations::EffectGeom,
    cursor: Option<(u16, u16)>,
    pet: &aterm_effects::companion::CompanionFrame,
    present: bool,
    mut cat_frame: crate::kitty_cursor::CatFrame,
    animate_head: bool,
    kitty_alpha: u8,
    now: Instant,
    notes_reduced: bool,
    default_bg: u32,
    cursor_color: u32,
    accent: u32,
) -> u64 {
    let mut fp = 0;
    // One body, one match ([`CompanionDuty`]): a seam that set both alphas
    // cannot draw two companions.
    let duty = cursor_companion_duty(pet.on_glass, kitty_alpha, cursor);
    // THE COMPANION SEAM ([`route_v2_companion`]): Rainbow Kitty v2's one
    // call, before either body is drawn, so the impulse and the seat land on
    // the frame copy the arms below emit. The composed path's twin is in
    // `compose_cursor_companion`.
    route_v2_companion(
        ws,
        CompanionInk::Single,
        duty,
        now,
        geom,
        &mut cat_frame,
        animate_head,
    );
    if let CompanionDuty::Pet = duty {
        fp ^= emit_resident_pet(
            ws,
            pet,
            cat_frame.look.normalized(),
            CompanionInk::Single,
            present,
            now,
            aterm_effects::companion::ContrastFallback {
                bg: default_bg,
                cursor: cursor_color,
                accent,
            },
        );
    }

    if let CompanionDuty::FlyingHead { cell } = duty {
        let layout = aterm_effects::word_decorations::KittyCursorLayout {
            geom,
            cursor: cell,
            look: cat_frame.render_look(),
            bob: cat_frame.bob,
        };
        let placement_frame = ws.fx.companions_mut().cursor_cat.placement_frame(now);
        if let Some(placement) = ws
            .fx
            .decos_mut()
            .resolve_kitty_cursor_placement(layout, placement_frame)
        {
            let colors = ws
                .fx
                .companions_mut()
                .cursor_cat
                .episode_colors()
                .unwrap_or_else(|| {
                    let sampled = cursor_cat_color_key(
                        &ws.input_scratch.cells,
                        geom,
                        placement.sample,
                        default_bg,
                        cursor_color,
                        accent,
                    );
                    ws.fx
                        .companions_mut()
                        .cursor_cat
                        .colors_for_episode(sampled)
                });
            let notes = {
                let c = ws.fx.companions_mut();
                c.music_notes
                    .update(now, c.kitty_sing.is_armed(now), c.kitty_sing.beat(now));
                c.music_notes.frame_array(now, notes_reduced)
            };
            if let Some(cursor_art_fp) = ws.fx.draw_flying_head(
                CompanionInk::Single.canvas(),
                aterm_effects::word_decorations::KittyCursorFrame {
                    geom,
                    cursor: cell,
                    look: layout.look,
                    colors,
                    bob: cat_frame.bob,
                    alpha: kitty_alpha,
                    pose: cat_frame.pose,
                    sing: cat_frame.sing,
                    notes,
                },
                placement,
            ) {
                fp ^= cursor_art_fp.rotate_left(29);
            }
        }
    }
    fp
}

/// The performance seam, host half: the ceremony is committed where it renders.
/// Dress the pet's owner with this window's verdict (the look the flying cat
/// latched, the tenure gate's authorised arrival and the winning rung), let the
/// owner draw the pair it wears, and spend the tenure's hello only for a drawn
/// `present`, never for a capture splice. Both sync sites
/// ([`emit_single_cursor_companion`], `App::compose_pet_companion`) call it.
/// The single grid draws into the window's sprite channel, the composed pane
/// into the pane staging channel the caller places.
pub(crate) fn emit_resident_pet(
    ws: &mut WindowState,
    pet: &aterm_effects::companion::CompanionFrame,
    look: aterm_effects::kitty_registry::KittyLook,
    ink: CompanionInk,
    present: bool,
    now: Instant,
    fallback: aterm_effects::companion::ContrastFallback,
) -> u64 {
    let cells: &[Vec<RenderCell>] = match ink {
        CompanionInk::Single => &ws.input_scratch.cells,
        CompanionInk::Composed => &ws.composed_focus_scratch.cells,
    };
    let arrival = ws.fx.look().tenure().arrival();
    let rung = ws.fx.look().rung();
    ws.fx
        .companion_mut()
        .set_look((look.coat, look.iris), arrival, rung);
    let (fp, outcome) = ws.fx.draw_pet(ink.canvas(), pet, cells, fallback);
    if ws.fx.companion().commit_hello_due(present, outcome) {
        ws.fx.look_mut().tenure_mut().commit_hello(now);
    }
    fp
}

#[cfg(test)]
mod resident_pet_presentation_tests {
    //! The host half of the resident's presentation. The pure laws (the
    //! owner gate, custody, the shed envelope, the yield box, the pane-bound
    //! ink read) are the engine's, pinned in `aterm_effects::companion`; what
    //! is left here is this host's emitter driven by the one owner.
    use aterm_effects::host::CaptureMode;
    use aterm_effects::kitty_pet::PetSense;
    use std::time::{Duration, Instant};

    /// The motion POLICY's posture (OS Reduce Motion, `motion = "reduced"`,
    /// an unfocused window) — never the load shed's, which keeps the
    /// resident's motion (`aterm_effects::companion::RESIDENT_SHED_CADENCE`).
    #[test]
    fn a_reduced_motion_resident_keeps_full_body_cursor_home_and_no_frame_debt() {
        let mut app = crate::App::headless_for_test();
        let geom = aterm_effects::word_decorations::EffectGeom {
            cell_w: 10,
            cell_h: 20,
            rows: 30,
            cols: 80,
        };
        let ws = app.windows.get_mut(&crate::WindowId(0)).unwrap();
        let start = Instant::now();
        let mut tick = 0;
        // Move the caret between episodes to prove the stationary posture
        // still follows actual input on the next frame.
        for caret_col in [12_u16, 60, 8, 48] {
            let caret = (4, caret_col);
            let mut previous = None;
            for _ in 0..20 {
                let now = start + Duration::from_millis(tick * 16);
                tick += 1;
                // The reduced-motion posture: static, full body.
                let pet = crate::app_render::pet_owner_tick_for_test(
                    ws,
                    CaptureMode::Present,
                    PetSense {
                        caret_drawn: true,
                        now,
                        caret: Some(caret),
                        rows: geom.rows,
                        cols: geom.cols,
                        cell_w: geom.cell_w,
                        cell_h: geom.cell_h,
                        reduced_motion: true,
                        output_burst: false,
                        pointer: None,
                        wrapped: false,
                    },
                );
                assert!(pet.on_glass);
                assert_eq!(pet.pet.alpha, 255, "the posture must not fade the resident");
                let body = pet.body_px.expect("the static resident is drawn");
                assert!(body.1 - body.0 >= 5 * i32::from(geom.cell_w));
                assert!(body.3 - body.2 >= i32::from(geom.cell_h));
                let cursor_x = i32::from(caret.1) * i32::from(geom.cell_w);
                assert!(
                    (body.0 - cursor_x).max(cursor_x - body.1).max(0)
                        <= 10 * i32::from(geom.cell_w)
                );
                assert!(
                    !ws.fx.companion_mut().needs_frames(),
                    "a retained static body owes no idle animation"
                );
                if let Some(previous) = previous {
                    assert_eq!(pet.fp, previous, "idle frames remain byte-stable");
                }
                previous = Some(pet.fp);
                assert!(ws.fx.companion_mut().hit_rect().is_some());
                ws.fx.open_words();
                let head = ws.fx.companions_mut().cursor_cat.static_frame(now);
                let fp = super::emit_single_cursor_companion(
                    ws,
                    geom,
                    Some(caret),
                    &pet,
                    false,
                    head,
                    false,
                    0,
                    now,
                    true,
                    0x0010_1010,
                    0x00FF_FFFF,
                    0x0050_FA7B,
                );
                assert_ne!(fp, 0);
                assert_eq!(
                    ws.fx.free_sprites().len(),
                    1,
                    "the static posture emits only its full body"
                );
                assert!(ws.fx.free_sprites()[0].w >= 5 * geom.cell_w);
            }
        }
        // Genuine ownership loss remains an immediate negative control.
        ws.fx.companion_mut().retire();
        assert!(
            !ws.fx.companion_mut().brain().is_active() && !ws.fx.companion_mut().needs_frames()
        );
    }
}

/// The redraw early-out decision, pure for unit tests: `true` (repaint) iff
/// this is the first frame (`prev` is `None`) or any presented-state term
/// changed since the last present. A steady screen with the same blink phase,
/// no bell flash and the same selection and cursor override skips extract,
/// rasterize and present.
#[cfg_attr(
    test,
    aterm_spec::refines(
        machine = "AsymmetricPadLayout",
        action = "RenderWithLayoutCache",
        project = "aterm_gui::app_render::project_asymmetric_pad_layout_key"
    )
)]
pub(crate) fn should_repaint(prev: Option<RepaintKey>, cur: RepaintKey) -> bool {
    prev != Some(cur)
}

/// A requested recovery frame bypasses the content-key cache until a real
/// present/drop acknowledges it. Shared by single-pane and split composition so
/// a raw resize/de-occlusion cannot be swallowed merely because terminal cells
/// stayed byte-identical.
#[inline]
pub(crate) fn should_repaint_or_recover(
    prev: Option<RepaintKey>,
    cur: RepaintKey,
    recovery_redraw_outstanding: bool,
) -> bool {
    recovery_redraw_outstanding || should_repaint(prev, cur)
}

/// Concrete GUI projection named by the asymmetric-layout refinement anchors.
/// It reads the load-bearing field directly from the exact key the redraw gate
/// stores and compares; no parallel fingerprint can drift from it.
#[cfg(test)]
pub(crate) fn project_asymmetric_pad_layout_key(key: &RepaintKey) -> usize {
    key.grid_top
}

/// Async fallback-face convergence, pure for unit tests. A font zoom or config
/// reload rebuilds the renderer, which parses the fallback faces on a
/// background thread; until they land, uncovered code points render as
/// provisional `.notdef` boxes. Given whether a parse is in flight this present
/// (`pending`) and at the previous one (`was`), returns `(rearm, invalidate)`:
///
/// * `rearm`: request another redraw and clear `last_present`. The early-out
///   ([`should_repaint`] and the `redraw_compose` twin) has no term for the
///   parse state or `font_epoch`, so without the clear an idle screen would
///   swallow the redraw and strand the boxes.
/// * `invalidate`: on the pending→landed edge only, drop the GPU present cache
///   so the re-resolved glyphs reach glass (the damage diff cannot see
///   `font_epoch`).
///
/// Steady state (`pending == was == false`) is `(false, false)`.
#[must_use]
pub(crate) fn fallback_convergence_action(pending: bool, was: bool) -> (bool, bool) {
    let converging = pending || was;
    (converging, converging && !pending)
}

/// VI-1: map a vi cursor grid `line` (live-top-relative; negative = scrolled into
/// history) to a visible screen row, given the `display_offset` (rows the viewport is
/// scrolled up from the live bottom) and the pane's `rows`. `None` when the vi cursor
/// sits off the current viewport (then the normal cursor is shown). Pure, so the
/// coordinate law is unit-tested without a window.
#[must_use]
fn vi_screen_row(vi_line: i32, display_offset: i32, rows: usize) -> Option<usize> {
    let r = vi_line + display_offset;
    (r >= 0 && (r as usize) < rows).then_some(r as usize)
}

/// Frame-hold decision for DEC-2026 synchronized output, pure for unit tests.
/// Inputs: the pane's sync state (`sync_active`), whether it was active at the
/// previous present (`was_active`), the armed deadline (`armed`), `now`, the
/// safety `timeout`, and the terminal's sync-close counter (`end_seq`, vs
/// `armed_end_seq` recorded at arm time). Returns `(new_deadline, hold,
/// new_armed_end_seq)`:
///
/// * Arm on the rising edge (`sync_active && !was_active`) at `now + timeout`,
///   recording `end_seq`.
/// * Hold while armed and unexpired: the caller skips the present so the app's
///   update lands tear-free.
/// * Close-and-re-arm when the level is still true but `end_seq` advanced: the
///   armed bracket closed and a new one opened. Present only if the new bracket
///   is still clean (`open_dirty` keeps it held). This gives one present per
///   closed bracket for an app that brackets every repaint under flood.
/// * Release (`hold == false`, `new_deadline == None`) when sync ends or the
///   deadline passes. The deadline is cleared so `about_to_wait` never folds a
///   past instant, and since arming is rising-edge-only a timed-out app presents
///   normally until its bracket closes.
#[must_use]
fn sync_frame_hold(
    observation: SyncObservation,
    was_active: bool,
    armed: Option<std::time::Instant>,
    armed_end_seq: u64,
    now: std::time::Instant,
    timeout: std::time::Duration,
) -> (Option<std::time::Instant>, bool, u64) {
    if !observation.active {
        return (None, false, observation.end_seq);
    }
    if was_active && observation.end_seq != armed_end_seq {
        // The armed bracket closed and another opened within one batch. The
        // current grid still equals the completed boundary only while the new
        // episode is clean; once it is dirty there is no old grid left to
        // present, so keep holding rather than expose partial next-frame cells.
        return (
            Some(now + timeout),
            observation.open_dirty,
            observation.end_seq,
        );
    }
    let mut deadline = if !was_active {
        Some(now + timeout) // rising edge: arm
    } else {
        armed // still active mid-episode: keep the armed deadline (may be expired)
    };
    let hold = deadline.is_some_and(|d| now < d);
    if !hold {
        deadline = None; // released: no stale past-deadline for about_to_wait to fold
    }
    (deadline, hold, observation.end_seq)
}

/// Apply [`sync_frame_hold`] to one window and publish its observability
/// counters; shared by the one-pane and composed present paths so both run the
/// same arm/release machine.
fn note_sync_hold_transition(
    sync_active: bool,
    was_active: bool,
    previous_deadline: Option<Instant>,
    deadline: Option<Instant>,
    sync_end_seq: u64,
    armed_end_seq: u64,
) {
    let closed_and_rearmed = sync_active && was_active && sync_end_seq != armed_end_seq;
    if (sync_active && !was_active) || closed_and_rearmed {
        metrics::note_sync_armed();
    }
    if closed_and_rearmed {
        metrics::note_sync_release_end();
    } else if previous_deadline.is_some() && deadline.is_none() {
        if sync_active {
            metrics::note_sync_release_timeout();
        } else {
            metrics::note_sync_release_end();
        }
    }
}

/// One terminal's DEC-2026 step, shared by the all-pane fold and the
/// under-lock recheck: find (or seed) the terminal's slot, advance
/// [`sync_frame_hold`], publish the transition's counters, and write the new
/// state back. Returns `(hold, deadline)`.
fn step_sync_pane_hold(
    holds: &mut Vec<crate::ComposedSyncPaneHold>,
    observation: SyncObservation,
    now: Instant,
    timeout: Duration,
) -> (bool, Option<Instant>) {
    let index = holds
        .iter()
        .position(|state| state.terminal_id == observation.terminal_id)
        .unwrap_or_else(|| {
            holds.push(crate::ComposedSyncPaneHold {
                terminal_id: observation.terminal_id,
                was_active: false,
                hold_until: None,
                armed_end_seq: observation.end_seq,
            });
            holds.len() - 1
        });
    let state = &mut holds[index];
    let (deadline, hold, armed_seq) = sync_frame_hold(
        observation,
        state.was_active,
        state.hold_until,
        state.armed_end_seq,
        now,
        timeout,
    );
    note_sync_hold_transition(
        observation.active,
        state.was_active,
        state.hold_until,
        deadline,
        observation.end_seq,
        state.armed_end_seq,
    );
    state.was_active = observation.active;
    state.hold_until = deadline;
    state.armed_end_seq = armed_seq;
    (hold, deadline)
}

#[must_use]
fn update_sync_frame_hold(
    window: &mut WindowState,
    observation: SyncObservation,
    now: Instant,
    timeout: Duration,
) -> bool {
    update_sync_frame_holds(window, &[observation], now, timeout)
}

/// Per-terminal composed-route twin of [`update_sync_frame_hold`]. Each
/// visible terminal owns its own close counter and deadline; the composite is
/// held while any member is held. This prevents one pane's completed bracket
/// from releasing a sibling pane's still-partial update.
#[must_use]
fn update_composed_sync_frame_hold(
    window: &mut WindowState,
    observations: &[SyncObservation],
    now: Instant,
    timeout: Duration,
) -> bool {
    update_sync_frame_holds(window, observations, now, timeout)
}

#[must_use]
fn update_sync_frame_holds(
    window: &mut WindowState,
    observations: &[SyncObservation],
    now: Instant,
    timeout: Duration,
) -> bool {
    window.sync_holds.retain(|state| {
        observations
            .iter()
            .any(|observation| observation.terminal_id == state.terminal_id)
    });

    let mut any_hold = false;
    let mut earliest_deadline: Option<Instant> = None;
    for (observation_index, &observation) in observations.iter().enumerate() {
        // The same terminal can be visible through more than one view. Its
        // protocol edge is still one event; folding it twice would turn the
        // close+rearm Allow decision into an immediate Hold just like a second
        // extraction recheck. The first occurrence owns the state transition.
        if observations[..observation_index]
            .iter()
            .any(|seen| seen.terminal_id == observation.terminal_id)
        {
            continue;
        }
        let (hold, deadline) =
            step_sync_pane_hold(&mut window.sync_holds, observation, now, timeout);
        any_hold |= hold;
        if let Some(deadline) = deadline {
            earliest_deadline = Some(earliest_deadline.map_or(deadline, |old| old.min(deadline)));
        }
    }
    window.sync_hold_until = earliest_deadline;
    window.sync_release_retry_at = None;
    window.sync_holding_gauge.set(any_hold);
    any_hold
}

/// Under-lock recheck for one member after the all-pane preflight. This does
/// not prune sibling state; it closes the enter-2026 race between the
/// sequential preflight and this pane's actual extraction lock.
#[must_use]
fn recheck_sync_frame_hold(
    window: &mut WindowState,
    preflight: SyncObservation,
    current: SyncObservation,
    now: Instant,
    timeout: Duration,
) -> bool {
    // The all-pane preflight already advanced this terminal's edge machine.
    // Re-applying an identical observation is not idempotent at the one-frame
    // close+reopen boundary: preflight deliberately allows that completed
    // bracket while arming the next episode, and a second transition would
    // immediately hold the newly armed episode instead. Only a terminal state
    // that actually changed in the lock gap needs another transition.
    if preflight == current {
        return false;
    }
    if preflight.terminal_id != current.terminal_id {
        // The pane changed terminal identity after the plan snapshot: do not
        // authorize extraction against a different owner. The next redraw
        // rebuilds the visible set.
        return true;
    }
    let (hold, _) = step_sync_pane_hold(&mut window.sync_holds, current, now, timeout);
    window.sync_hold_until = window
        .sync_holds
        .iter()
        .filter_map(|state| state.hold_until)
        .min();
    window.sync_release_retry_at = None;
    let any_hold = window
        .sync_holds
        .iter()
        .any(|state| state.hold_until.is_some_and(|deadline| now < deadline));
    window.sync_holding_gauge.set(any_hold);
    hold
}

#[cfg(test)]
mod vi_render_tests {
    use super::vi_screen_row;

    /// VI-1: the vi cursor grid line → visible screen row map. `screen = line +
    /// display_offset`, drawn only when it lands inside `[0, rows)` (else the normal
    /// cursor shows).
    #[test]
    fn vi_screen_row_maps_line_through_display_offset() {
        // At the bottom (offset 0): live top line 0 → row 0; line rows-1 → last row.
        assert_eq!(vi_screen_row(0, 0, 24), Some(0));
        assert_eq!(vi_screen_row(23, 0, 24), Some(23));
        // A scrollback line (negative) is off-viewport at offset 0 → not drawn.
        assert_eq!(vi_screen_row(-3, 0, 24), None);
        // Scrolled up 5: that same scrollback line -3 now sits at row 2.
        assert_eq!(vi_screen_row(-3, 5, 24), Some(2));
        // A live line pushed past the bottom by the scroll → off-viewport.
        assert_eq!(vi_screen_row(23, 5, 24), None);
        // Exactly at the bottom edge is out of range (rows is exclusive).
        assert_eq!(vi_screen_row(24, 0, 24), None);
    }
}

#[cfg(test)]
#[path = "app_render_sync_hold_tests.rs"]
mod sync_hold_tests;

#[cfg(test)]
mod fallback_convergence_tests {
    use super::fallback_convergence_action;

    /// `fallback_convergence_action(pending, was_pending) -> (re-arm, invalidate)`,
    /// its whole four-row truth table.
    #[test]
    fn fallback_convergence_truth_table() {
        let rows = [
            // The rising edge + steady-pending frames: keep re-arming (which clears
            // `last_present`, forcing the frame past the content early-out) but do
            // Not invalidate the GPU present cache yet — the real glyphs have not
            // landed.
            (
                true,
                false,
                (true, false),
                "first pending frame: re-arm, no invalidate",
            ),
            (
                true,
                true,
                (true, false),
                "steady pending frame: re-arm, no invalidate",
            ),
            // The pending→landed edge: re-arm and invalidate the GPU present
            // cache so the re-resolved glyphs reach glass.
            (
                false,
                true,
                (true, true),
                "landing edge: re-arm AND invalidate",
            ),
            // Steady state (no parse in flight or just landed) is a no-op, so an
            // idle screen never churns presents; a converging frame always
            // clears `last_present` alongside the re-arm.
            (
                false,
                false,
                (false, false),
                "not converging: no re-arm, no invalidate",
            ),
        ];
        for (pending, was, want, why) in rows {
            assert_eq!(fallback_convergence_action(pending, was), want, "{why}");
        }
    }
}

/// The band's landing schedules itself (Windows, Linux): a CJK tab title's
/// first frame takes the strip's cell lane, and that present parses the chain
/// face the chrome then draws with. Nothing else asks for the next frame, so
/// the post-present follow-up asks for it, exactly once.
#[cfg(all(test, any(windows, target_os = "linux")))]
mod strip_band_landing_tests {
    use super::*;
    use crate::tab_bar::TabHit;

    /// One composed frame up to the present, as the redraw builds it: the
    /// front terminal's cells into the window's scratch, then the strip spliced
    /// above them (the cold `splice_tab_strip` refills the titles the hot path
    /// shares with the RepaintKey).
    fn compose(app: &mut App, wid: WindowId) {
        let (rows, cols) = {
            let ws = &app.windows[&wid];
            (ws.rows, ws.cols)
        };
        let terminal = app
            .front_terminal(wid)
            .expect("front terminal")
            .term
            .clone();
        {
            let ws = app.windows.get_mut(&wid).expect("window");
            let mut term = term_lock(&terminal);
            term.resize(rows, cols);
            term.cell_frame_into(&mut ws.input_scratch, usize::from(rows), usize::from(cols));
        }
        app.splice_tab_strip(wid);
    }

    /// The present's raster of the composed frame through the app's own CPU
    /// renderer — the live terminal engine whose chain cells the chrome's seed
    /// shares. This is where a cell-lane ideograph parses its chain face.
    fn present_raster(app: &mut App, wid: WindowId) {
        let App {
            windows, backend, ..
        } = app;
        let ws = windows.get(&wid).expect("window");
        let Backend::Cpu(renderer) = backend.ready_mut() else {
            panic!("headless test backend is CPU")
        };
        let _ = renderer.render_input(&ws.input_scratch);
    }

    /// Whether the cached band covers strip column `col` with the band image.
    fn band_covers(app: &App, wid: WindowId, col: usize) -> bool {
        let band = &app.windows[&wid].cached_strip_band;
        let Some(row) = band.first() else {
            return false;
        };
        let Some((_, first)) = row.first() else {
            return false;
        };
        row.iter()
            .any(|(c, r)| *c == col && Arc::ptr_eq(&r.image, &first.image))
    }

    /// The real post-present follow-up, windowless.
    fn finalize(app: &mut App, wid: WindowId) {
        let plan = app.active_visible_leaf_plan(wid).expect("visible plan");
        app.finalize_successful_present(
            wid,
            crate::metrics::StartupPresentTiming::collapsed(Instant::now()),
            0,
            None,
            SuccessfulPresentRoute::Terminal,
            crate::VisibleContentRoute::Terminal { composed: false },
            HostVisualState::default(),
            &plan,
        );
    }

    /// Two composed frames of a CJK-titled strip with a steady cursor and no
    /// other stimulus between them — the only thing that runs between the two
    /// is the first frame's present and its follow-up. Frame 1 is the defect's
    /// frame (cell lane); its present parses the chain face; the follow-up
    /// re-arms and requests a redraw; frame 2 is a band title, under a band key
    /// that differs from frame 1's by the epoch term alone; and the follow-up
    /// after frame 2 asks for nothing more.
    #[test]
    fn a_cjk_title_lands_in_the_band_on_the_next_frame_with_no_other_stimulus() {
        let Some(path) = crate::tray_raster::cjk_chain_face_path_for_test() else {
            return;
        };
        let mut app = App::headless_for_test();
        let wid = WindowId(0);
        app.tab_strip_rows = 1;
        // The first present is behind us: the follow-up must not re-seed the
        // chrome over the seed installed below.
        app.first_present_done = true;
        // A second tab, titled as the finding names it (OSC 0 with CJK), with
        // its cursor pinned steady by DECSCUSR — the blink clock is not armed.
        let session = crate::stub_session(app.next_session_id);
        app.push_stub_tab(wid, session);
        let terminal = app
            .front_terminal(wid)
            .expect("front terminal")
            .term
            .clone();
        {
            let mut term = term_lock(&terminal);
            term.process("\x1b[2 q\x1b]0;日本語 shell\x07".as_bytes());
            assert!(
                !crate::blink_clock_armed(term.cursor_visible(), term.cursor_style(), false),
                "a steady cursor: the blink clock is not armed"
            );
        }
        // The live renderer is the app's own backend. The chrome's seed is a
        // fork of its SEALED generation over the same chain cells — the
        // window's order (seal, then fork) — installed dormant: no worker, so
        // nothing can land through the store; only the terminal's draw can.
        let seed = {
            let App {
                backend,
                font_px,
                theme,
                ..
            } = &mut app;
            let Backend::Cpu(renderer) = backend.ready_mut() else {
                panic!("headless test backend is CPU")
            };
            renderer.set_runtime_font_discovery(false);
            renderer.set_config_fallback_fonts(&[path.to_string()]);
            let _ = renderer.seal_admitted_font_sources();
            renderer
                .fork_semantic_surface(*font_px, *theme)
                .expect("a sealed generation forks")
        };
        crate::tray_raster::install_dormant_chrome_fonts_for_test(seed);
        crate::tray_raster::prepare_ui_fonts_for_direct_view_test();
        if !crate::tray_raster::strip_band_ui_ready() {
            crate::tray_raster::clear_ui_fonts_for_test();
            return;
        }

        // Frame 1: the chain face is unparsed, the title is not coverable, and
        // the segment goes to the cell lane — the defect's frame.
        compose(&mut app, wid);
        let seg = app.windows[&wid]
            .tab_segments
            .iter()
            .find(|s| matches!(s.kind, TabHit::Select(1)))
            .copied()
            .expect("the CJK tab's segment");
        let probe = usize::from(seg.start_col) + 1;
        let first_key = app.windows[&wid].strip_band_key;
        assert!(
            !band_covers(&app, wid, probe),
            "frame 1: the CJK segment is the cell lane's (the chain face is unparsed)"
        );
        // Its present: the strip cells raster through the live renderer, whose
        // draw of the ideograph parses the chain face into the shared cell…
        present_raster(&mut app, wid);
        // …and stamps the frame's key, as every real present does — the
        // early-out that would swallow a bare redraw request.
        {
            let key =
                crate::early_out_tests::frame_key(&mut term_lock(&terminal), false, false, None);
            app.windows
                .get_mut(&wid)
                .expect("window")
                .stamp_present_decision(key);
        }
        assert!(app.windows[&wid].last_present.is_some());
        // The post-present follow-up, the real one: it notices the landing and
        // re-arms the frame.
        finalize(&mut app, wid);
        assert!(
            app.windows[&wid].last_present.is_none(),
            "the follow-up cleared the retained key after the first present"
        );
        // The request edge, on the seam the follow-up fired through (the
        // decision stands until the next splice re-reads the epoch).
        let mut requests = 0;
        assert!(app.rearm_for_strip_band_landing(wid, || requests += 1));
        assert_eq!(
            requests, 1,
            "a redraw was requested after the first present"
        );

        // Frame 2, with nothing else having happened — no keystroke, no output,
        // no focus change, no blink: the splice misses the band cache on the
        // epoch alone and the title is a band title.
        compose(&mut app, wid);
        let second_key = app.windows[&wid].strip_band_key;
        assert_eq!(
            (first_key.0, first_key.1, first_key.2, first_key.3),
            (second_key.0, second_key.1, second_key.2, second_key.3),
            "the geometry terms did not move"
        );
        assert_ne!(
            first_key.4, second_key.4,
            "the landing moved the band key's epoch term"
        );
        assert!(
            band_covers(&app, wid, probe),
            "frame 2: the CJK segment is band-covered"
        );
        // Converged: the splice cached the live epoch, so the follow-up asks for
        // nothing — one extra frame per landing, never a loop.
        let mut requests = 0;
        assert!(!app.rearm_for_strip_band_landing(wid, || requests += 1));
        assert_eq!(requests, 0, "a settled band requests no frame");
        crate::tray_raster::clear_ui_fonts_for_test();
    }

    /// The follow-up is a no-op wherever there is no landing: a window whose
    /// strip is off never wrote a band key (the zero sentinel is not a stale
    /// epoch), and a settled band's re-read is not a landing — otherwise an
    /// idle window would churn presents.
    #[test]
    fn no_landing_no_rearm() {
        let mut app = App::headless_for_test();
        let wid = WindowId(0);
        let renderer = aterm_render::Renderer::from_bytes(
            aterm_render::embedded_font(),
            14.0,
            aterm_render::Theme::default(),
        )
        .expect("embedded renderer");
        crate::tray_raster::install_dormant_chrome_fonts_for_test(renderer);
        let mut requests = 0;
        app.tab_strip_rows = 0;
        assert!(
            !app.rearm_for_strip_band_landing(wid, || requests += 1),
            "no strip: nothing to land"
        );
        app.tab_strip_rows = 1;
        compose(&mut app, wid);
        assert!(
            !app.rearm_for_strip_band_landing(wid, || requests += 1),
            "a settled band's re-read is not a landing"
        );
        assert_eq!(requests, 0);
        crate::tray_raster::clear_ui_fonts_for_test();
    }
}

/// Coalesce a per-row dirty set into inclusive `(first, last)` runs of
/// consecutive dirty rows — the CPU present path copies one surface band and
/// reports one damage rect per run. A pure function (no window, no renderer)
/// so the run computation the damage rects rely on is unit testable.
pub(crate) fn dirty_row_runs(dirty: &[bool]) -> impl Iterator<Item = (usize, usize)> + '_ {
    let mut row = 0usize;
    std::iter::from_fn(move || {
        while row < dirty.len() && !dirty[row] {
            row += 1;
        }
        if row >= dirty.len() {
            return None;
        }
        let start = row;
        while row < dirty.len() && dirty[row] {
            row += 1;
        }
        Some((start, row - 1))
    })
}

/// Build the exact CPU-present damage rectangles for dirty renderer row bands.
/// The caller owns `out`, so a stable row count retains its allocation. Geometry
/// is pure: `row_pixel_band` supplies the renderer's source `[y0, y1)` for one
/// grid row; cropping and the 1x1 empty fallback are resolved here once for both
/// the live presenter and deterministic tests.
fn cpu_damage_rects_into(
    out: &mut Vec<crate::present::DamageRect>,
    dirty: &[bool],
    x0: usize,
    span: usize,
    off_y: i64,
    surface_height: usize,
    mut row_pixel_band: impl FnMut(usize) -> (usize, usize),
) -> bool {
    out.clear();
    out.reserve(dirty.len().div_ceil(2).max(1));
    let Some(width) = NonZeroU32::new(span as u32) else {
        let one = NonZeroU32::new(1).expect("one is non-zero");
        out.push(crate::present::DamageRect {
            x: 0,
            y: 0,
            width: one,
            height: one,
        });
        return false;
    };
    let surface_height = i64::try_from(surface_height).unwrap_or(i64::MAX);
    for (r0, r1) in dirty_row_runs(dirty) {
        let (fy0, _) = row_pixel_band(r0);
        let (_, fy1) = row_pixel_band(r1);
        let lo = i64::try_from(fy0)
            .unwrap_or(i64::MAX)
            .saturating_add(off_y)
            .clamp(0, surface_height);
        let hi = i64::try_from(fy1)
            .unwrap_or(i64::MAX)
            .saturating_add(off_y)
            .clamp(0, surface_height);
        if lo < hi
            && let Some(height) = NonZeroU32::new(u32::try_from(hi - lo).unwrap_or(u32::MAX))
        {
            out.push(crate::present::DamageRect {
                x: x0 as u32,
                y: lo as u32,
                width,
                height,
            });
        }
    }
    let copied = !out.is_empty();
    if !copied {
        let one = NonZeroU32::new(1).expect("one is non-zero");
        out.push(crate::present::DamageRect {
            x: 0,
            y: 0,
            width: one,
            height: one,
        });
    }
    copied
}

#[cfg(test)]
mod cpu_damage_rect_tests {
    use super::cpu_damage_rects_into;

    fn tuples(rects: &[crate::present::DamageRect]) -> Vec<(u32, u32, u32, u32)> {
        rects
            .iter()
            .map(|rect| (rect.x, rect.y, rect.width.get(), rect.height.get()))
            .collect()
    }

    #[test]
    fn dirty_damage_geometry_is_exact_and_reuses_its_allocation() {
        let dirty = [true, true, false, true, false, true, true];
        let mut rects = Vec::new();
        let build = |rects: &mut Vec<crate::present::DamageRect>| {
            cpu_damage_rects_into(rects, &dirty, 3, 8, -5, 55, |row| {
                (row * 10, (row + 1) * 10)
            })
        };

        assert!(build(&mut rects));
        assert_eq!(
            tuples(&rects),
            vec![(3, 0, 8, 15), (3, 25, 8, 10), (3, 45, 8, 10)],
            "contiguous rows coalesce and top/bottom cropping stays exact",
        );

        let allocation = rects.as_ptr();
        let capacity = rects.capacity();
        assert!(build(&mut rects));
        assert_eq!(rects.as_ptr(), allocation, "steady rows reuse the Vec");
        assert_eq!(rects.capacity(), capacity, "steady rows do not grow it");
    }

    #[test]
    fn empty_or_zero_span_uses_the_same_minimal_fallback() {
        for (dirty, span) in [([false, false], 8), ([true, true], 0)] {
            let mut rects = Vec::new();
            assert!(!cpu_damage_rects_into(
                &mut rects,
                &dirty,
                3,
                span,
                0,
                20,
                |row| (row * 10, (row + 1) * 10),
            ));
            assert_eq!(tuples(&rects), vec![(0, 0, 1, 1)]);
        }
    }
}

/// The `RepaintKey::system_dark` term (and the overlay card raster's geom_key
/// term), as a pure function of the App-tracked OS appearance
/// (`sync_app_theme_to_appearance`). The one population source for every
/// key construction site — `os_appearance_flip_repaints` pins that a
/// tracked appearance flip moves this term, so it cannot silently decay to a
/// constant (which would let the auto titlebar mock composite stale through an
/// OS appearance flip whenever the rest of the key is idle).
pub(crate) fn repaint_system_dark(appearance: aterm_types::Appearance) -> bool {
    appearance == aterm_types::Appearance::Dark
}

/// I-2: invert a frame's RGB in place when a visual-bell flash is `active`,
/// matching the on-screen present's invert (CPU `src ^ 0x00ff_ffff`; the GPU
/// blit shader does the same). Packed `0x00RRGGBB`, so XOR the low 24 bits and
/// leave the unused top byte clear. A no-op when no flash is active, so the
/// steady-screen snapshot path is byte-identical to before.
pub(crate) fn apply_bell_invert(frame: &mut Frame, active: bool) {
    if !active {
        return;
    }
    for px in &mut frame.pixels {
        *px ^= 0x00ff_ffff;
    }
}

/// Where the renderer's content frame sits inside the raw destination surface:
/// a `frame_width`×`frame_height` frame at `(origin_x, origin_y)` within a
/// `surface_width`×`surface_height` window. The origin is the centred
/// [`aterm_render::band_offset`] (negative on a transient crop) and the
/// leftover is the platform-chrome band. One value because the six scalars
/// only mean something together.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct PlacedFrame {
    /// Raw destination surface extent (the whole window), in device pixels.
    surface_width: usize,
    surface_height: usize,
    /// Frame origin inside that surface; negative while the frame is cropped.
    origin_x: i64,
    origin_y: i64,
    /// Content frame extent, in device pixels.
    frame_width: usize,
    frame_height: usize,
}

/// Region-scoped twin used by the CPU window presenter after tray composition.
/// The remainder bands are platform chrome and stay uninverted, matching the
/// GPU blit's frame-relative effect.
fn apply_bell_invert_at(pixels: &mut [u32], placement: PlacedFrame, active: bool) {
    let PlacedFrame {
        surface_width,
        surface_height,
        origin_x,
        origin_y,
        frame_width,
        frame_height,
    } = placement;
    if !active || surface_width == 0 || surface_height == 0 {
        return;
    }
    for row in 0..frame_height {
        let y = origin_y.saturating_add(row as i64);
        if y < 0 || y >= surface_height as i64 {
            continue;
        }
        for col in 0..frame_width {
            let x = origin_x.saturating_add(col as i64);
            if x < 0 || x >= surface_width as i64 {
                continue;
            }
            if let Some(pixel) = pixels.get_mut(y as usize * surface_width + x as usize) {
                *pixel ^= 0x00ff_ffff;
            }
        }
    }
}

/// Device-pixel thickness of the drop-target accent border, scaled to the window
/// and clamped so it stays a thin frame on small windows and never dominates a
/// large one.
fn drop_border_px(w: usize, h: usize) -> usize {
    (w.min(h) / 200).clamp(2, 6)
}

/// Alpha (out of 255) of the faint full-grid accent wash and the inset border.
const DROP_WASH_ALPHA: u32 = 28; // ~11% — readable content underneath
const DROP_BORDER_ALPHA: u32 = 235; // ~92% — a crisp but not harsh frame

/// The parameters of one inset-accent-border overlay pass: the drag-and-drop drop
/// target (fixed [`DROP_WASH_ALPHA`]/[`DROP_BORDER_ALPHA`]) or the upgrade rim
/// (a pulsing alpha off [`crate::level_up`]). Threading a single descriptor
/// through the CPU present ([`apply_overlay_at`]), the GPU blit ([`aterm_gpu::DropOverlay`]),
/// and the SACRED `image`/`snapshot` compositor keeps the app-present destination
/// equal to what an AI reads.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct OverlayGlow {
    /// Overlay accent (packed `0x00RRGGBB`; the top byte is ignored).
    pub(crate) accent: u32,
    /// Interior full-grid wash alpha (0..255).
    pub(crate) wash_a: u8,
    /// Inset-border alpha (0..255).
    pub(crate) border_a: u8,
    /// Border thickness as a multiple of the size-derived law
    /// ([`drop_border_px`]), in 1/16 units; `0` (or `16`) is the plain law.
    /// The upgrade surge thickens its rim through this; the drop target never
    /// does. The GPU (`aterm_gpu::DropOverlay::border_scale_q4`) applies the
    /// same arithmetic, so both backends draw one rim.
    pub(crate) border_scale_q4: u8,
}

/// The size-derived border thickness scaled by an [`OverlayGlow::border_scale_q4`]
/// (1/16 units; `0` and `16` leave it alone), never below one pixel — the same
/// arithmetic as `aterm_gpu`'s twin.
fn scaled_border_px(base: usize, scale_q4: u8) -> usize {
    if scale_q4 == 0 {
        return base;
    }
    ((base * usize::from(scale_q4)) / 16).max(1)
}

#[cfg(test)]
mod scaled_border_px_tests {
    use super::scaled_border_px;

    /// The surge's rim-thickness law, pinned on both twins with one table (the
    /// GPU's is `aterm_gpu::renderer::scaled_border_px`): `0` means unscaled,
    /// sixteenths otherwise, never thinner than one pixel.
    #[test]
    fn scaled_border_px_is_sixteenths_never_thinner_than_a_pixel() {
        for (base, q4, want) in [
            (6, 0, 6),
            (6, 16, 6),
            (6, 24, 9),
            (6, 40, 15),
            (6, 44, 16),
            (1, 1, 1),
            (0, 16, 1),
            (0, 0, 0),
        ] {
            assert_eq!(scaled_border_px(base, q4), want, "base {base} × {q4}/16");
        }
    }
}

/// Blend `fg` over `bg` (both packed `0x00RRGGBB`) at alpha `a` (0..=255), per
/// channel, leaving the top byte clear. `a == 0` returns `bg`; `a == 255` returns
/// `fg`. The canonical coverage blend (mirrors the renderer's private `blend`).
fn blend_rgb(bg: u32, fg: u32, a: u32) -> u32 {
    let inv = 255 - a;
    let r = (((bg >> 16) & 0xff) * inv + ((fg >> 16) & 0xff) * a) / 255;
    let g = (((bg >> 8) & 0xff) * inv + ((fg >> 8) & 0xff) * a) / 255;
    let b = ((bg & 0xff) * inv + (fg & 0xff) * a) / 255;
    (r << 16) | (g << 8) | b
}

/// Composite the drag-and-drop drop-target highlight over a packed `0xTTRRGGBB`
/// framebuffer (TT is renderer transmittance): a faint `accent` wash across the whole grid plus a near-opaque
/// `accent` border inset at the window edge (the chosen "inset accent border +
/// faint wash" treatment). `pixels` is row-major `w * h` (any trailing pixels are
/// ignored). Test convenience for the fixed drag-highlight constants; production
/// presentation and capture pass their resolved `OverlayGlow` to `apply_overlay_at`.
/// The GPU backend reproduces the same look in its blit shader.
#[cfg(test)]
pub(crate) fn apply_drop_overlay(pixels: &mut [u32], w: usize, h: usize, accent: u32) {
    apply_drop_overlay_at(pixels, w, h, 0, 0, w, h, accent);
}

/// W1 band-aware twin of [`apply_drop_overlay`]: composite the drop-target
/// highlight over the content frame (`fw`×`fh`, sitting at `(ox, oy)` — the
/// centred [`aterm_render::band_offset`], possibly negative on a transient
/// crop) inside a RAW-window-sized surface (`sw`×`sh`). Border thickness and
/// edge distances are frame-relative, matching the GPU blit shader (whose band
/// early-out means the highlight never touches the padding bands); drawing is
/// clipped to the surface. With `ox == oy == 0` and `sw/sh == fw/fh` this is
/// byte-identical to the historical whole-frame overlay.
#[cfg(test)]
#[allow(
    clippy::too_many_arguments,
    reason = "a raw surface + a placed frame rect is irreducibly 7 geometry scalars; bundling them into a struct only relocates the list"
)]
pub(crate) fn apply_drop_overlay_at(
    pixels: &mut [u32],
    sw: usize,
    sh: usize,
    ox: i64,
    oy: i64,
    fw: usize,
    fh: usize,
    accent: u32,
) {
    // The drag-and-drop drop target is the fixed-alpha instance of the general glow.
    apply_overlay_at(
        pixels,
        sw,
        sh,
        ox,
        oy,
        fw,
        fh,
        OverlayGlow {
            accent,
            wash_a: DROP_WASH_ALPHA as u8,
            border_a: DROP_BORDER_ALPHA as u8,
            border_scale_q4: 0,
        },
    );
}

/// The alpha-parametrized CORE of the inset-accent-border overlay (the drop target's
/// fixed alphas or the upgrade rim's pulsing alpha), band-aware exactly like
/// the fixed-alpha test helper and pure + allocation-free. With the drop-overlay constants
/// this is exactly the fixed-alpha test helper (`apply_drop_overlay_at` calls it), whose
/// band shift `band_aware_overlay_twins_shift_without_touching_bands` pins.
#[allow(
    clippy::too_many_arguments,
    reason = "a raw surface + a placed frame rect is irreducibly 7 geometry scalars plus the glow; bundling them into a struct only relocates the list"
)]
pub(crate) fn apply_overlay_at(
    pixels: &mut [u32],
    sw: usize,
    sh: usize,
    ox: i64,
    oy: i64,
    fw: usize,
    fh: usize,
    glow: OverlayGlow,
) {
    if fw == 0 || fh == 0 || sw == 0 || sh == 0 {
        return;
    }
    let border = scaled_border_px(drop_border_px(fw, fh), glow.border_scale_q4)
        .min(fw / 2)
        .min(fh / 2)
        .max(1);
    let accent = glow.accent & 0x00ff_ffff;
    let (wash_a, border_a) = (u32::from(glow.wash_a), u32::from(glow.border_a));
    // The frame rows/cols visible on the surface (intersection; crop-safe).
    let y0 = ox_clamp(oy, sh);
    let y1 = (oy + fh as i64).clamp(0, sh as i64) as usize;
    let x0 = ox_clamp(ox, sw);
    let x1 = (ox + fw as i64).clamp(0, sw as i64) as usize;
    for y in y0..y1 {
        let fy = (y as i64 - oy) as usize; // frame-local row
        let edge_row = fy < border || fy >= fh - border;
        let Some(row) = pixels.get_mut(y * sw + x0..y * sw + x1) else {
            break;
        };
        for (i, px) in row.iter_mut().enumerate() {
            let fx = (x0 + i) as i64 - ox; // frame-local column
            let fx = fx as usize;
            let on_border = edge_row || fx < border || fx >= fw - border;
            let a = if on_border { border_a } else { wash_a };
            // The GPU blit treats this as a presentation tint and returns the
            // sampled alpha unchanged. Preserve the renderer's packed
            // transmittance byte here as well, so CPU application-present and
            // capture artifacts cannot become spuriously opaque while the
            // highlight is visible.
            let transmittance = *px & 0xff00_0000;
            *px = transmittance | blend_rgb(*px & 0x00ff_ffff, accent, a);
        }
    }
}

/// `off.max(0)` clamped into a `0..=len` surface coordinate.
fn ox_clamp(off: i64, len: usize) -> usize {
    off.clamp(0, len as i64) as usize
}

/// P3: composite the rasterized frosted Settings card (straight-alpha RGBA8, `cw*ch`
/// device px) over a packed `0xTTRRGGBB` framebuffer at device offset `(ox, oy)`. Pure +
/// allocation-free src-over (`out = src*a + dst*(1-a)`), the per-pixel-alpha twin of
/// [`apply_drop_overlay`], so the live CPU application-present composition and the
/// headless `image`/`snapshot` share one app-owned compositor. Fully clamped to the
/// surface; transparent card pixels (`a == 0`) leave the live terminal beneath untouched.
#[cfg(test)]
pub(crate) fn composite_tray(
    pixels: &mut [u32],
    fb_w: usize,
    fb_h: usize,
    card: &crate::SettingsCard,
) {
    composite_tray_at(pixels, fb_w, fb_h, 0, 0, card);
}

/// Project one cached tray card into the portion at or below `floor_y`.
///
/// Config-warning rows are painted into the cell framebuffer after the card is
/// rasterized, but tray pixels composite after cells.  Cropping the borrowed
/// view here (instead of destructively rewriting the cached card) preserves the
/// declared topmost banner ordering across CPU/GPU application-present paths
/// and captures. Every
/// shipping tray starts at the grid origin or below, so removing its leading
/// rows is exactly the intersection with the banner's top row band.
pub(crate) fn tray_quad_below_y(
    card: &crate::SettingsCard,
    floor_y: u32,
) -> Option<aterm_gpu::TrayQuad<'_>> {
    if card.pw == 0 || card.ph == 0 {
        return None;
    }
    let skipped_rows = floor_y.saturating_sub(card.dy).min(card.ph);
    if skipped_rows == card.ph {
        return None;
    }
    let stride = usize::try_from(card.pw).ok()?.checked_mul(4)?;
    let start = usize::try_from(skipped_rows).ok()?.checked_mul(stride)?;
    let remaining_rows = usize::try_from(card.ph - skipped_rows).ok()?;
    let end = start.checked_add(remaining_rows.checked_mul(stride)?)?;
    Some(aterm_gpu::TrayQuad {
        rgba: card.rgba.get(start..end)?,
        pw: card.pw,
        ph: card.ph - skipped_rows,
        dx: card.dx,
        dy: card.dy.saturating_add(skipped_rows),
    })
}

/// W1 band-aware twin of [`composite_tray`]: the card's `dx`/`dy` are frame
/// device coordinates, so on a raw-window-sized surface it lands shifted by the
/// frame's band offset `(ox, oy)` (possibly negative on a transient crop). With
/// `ox == oy == 0` this is byte-identical to the historical compositor. Fully
/// clamped to the surface, like the original.
#[cfg(test)]
pub(crate) fn composite_tray_at(
    pixels: &mut [u32],
    fb_w: usize,
    fb_h: usize,
    ox: i64,
    oy: i64,
    card: &crate::SettingsCard,
) {
    let Some(card) = tray_quad_below_y(card, 0) else {
        return;
    };
    composite_tray_quad_at(pixels, fb_w, fb_h, ox, oy, card);
}

/// Raw-quad twin used after [`tray_quad_below_y`] has cropped a cached card.
pub(crate) fn composite_tray_quad_at(
    pixels: &mut [u32],
    fb_w: usize,
    fb_h: usize,
    ox: i64,
    oy: i64,
    card: aterm_gpu::TrayQuad<'_>,
) {
    let (cw, ch) = (card.pw as usize, card.ph as usize);
    for ty in 0..ch {
        let py = i64::from(card.dy) + ty as i64 + oy;
        if py < 0 {
            continue;
        }
        let py = py as usize;
        if py >= fb_h {
            break;
        }
        let base = py * fb_w;
        for tx in 0..cw {
            let px = i64::from(card.dx) + tx as i64 + ox;
            if px < 0 || px >= fb_w as i64 {
                continue;
            }
            let px = px as usize;
            let i = (ty * cw + tx) * 4;
            let a = u32::from(card.rgba[i + 3]);
            if a == 0 {
                continue;
            }
            let Some(slot) = pixels.get_mut(base + px) else {
                continue;
            };
            let (sr, sg, sb) = (
                u32::from(card.rgba[i]),
                u32::from(card.rgba[i + 1]),
                u32::from(card.rgba[i + 2]),
            );
            let d = *slot;
            let (dr, dg, db) = ((d >> 16) & 0xff, (d >> 8) & 0xff, d & 0xff);
            let r = (sr * a + dr * (255 - a) + 127) / 255;
            let g = (sg * a + dg * (255 - a) + 127) / 255;
            let b = (sb * a + db * (255 - a) + 127) / 255;
            // Packed framebuffer alpha is represented as TRANSMITTANCE
            // (`T = 255 - A`). Straight-alpha source-over therefore composes
            // it as `T' = T_dst * (1 - A_src)`, the exact alpha-component twin
            // of the GPU tray pipeline's ALPHA_BLENDING state.
            let dst_t = (d >> 24) & 0xff;
            let out_t = (dst_t * (255 - a) + 127) / 255;
            *slot = (out_t << 24) | (r << 16) | (g << 8) | b;
        }
    }
}

/// Canonical CPU/capture frontend order, matching the GPU present pipeline:
/// renderer base, then tray/native card, then bell inversion, then the accent
/// overlay. Keeping this as one callable seam prevents a capture or CPU surface
/// from accidentally putting opaque tray pixels above a bell/drag effect.
#[allow(
    clippy::too_many_arguments,
    reason = "the placed renderer frame and raw destination require two dimensions plus an origin"
)]
pub(crate) fn apply_host_chrome_at(
    pixels: &mut [u32],
    surface_width: usize,
    surface_height: usize,
    origin_x: i64,
    origin_y: i64,
    frame_width: usize,
    frame_height: usize,
    tray: Option<aterm_gpu::TrayQuad<'_>>,
    invert: bool,
    overlay: Option<OverlayGlow>,
) {
    if let Some(tray) = tray {
        composite_tray_quad_at(
            pixels,
            surface_width,
            surface_height,
            origin_x,
            origin_y,
            tray,
        );
    }
    apply_bell_invert_at(
        pixels,
        PlacedFrame {
            surface_width,
            surface_height,
            origin_x,
            origin_y,
            frame_width,
            frame_height,
        },
        invert,
    );
    if let Some(overlay) = overlay {
        apply_overlay_at(
            pixels,
            surface_width,
            surface_height,
            origin_x,
            origin_y,
            frame_width,
            frame_height,
            overlay,
        );
    }
}

#[allow(
    clippy::items_after_test_module,
    reason = "these unit tests sit next to the drop-overlay helpers they cover; the rest of the file is the App render inherent-impl, not stray items"
)]
#[cfg(test)]
#[path = "app_render_drop_overlay_tests.rs"]
mod drop_overlay_tests;

/// Pure pixel→terminal-cell mapping (the body of [`App::pixel_to_cell`]). Three
/// insets are removed from the raw window pixel, in order:
///   * `head`: the chrome headroom above the padded grid, from `y` only; a
///     click in it saturates toward row 0;
///   * `pad`: the padding border around the whole window (strip included), from
///     both `x` and `y`, saturating to row/col 0;
///   * `strip_rows * ch`: the tab strip atop the pad-inset grid; a click in the
///     strip clamps to terminal row 0.
///
/// The result is clamped to the terminal grid.
#[allow(
    clippy::too_many_arguments,
    reason = "pure pixel->cell geometry over independent scalar inputs (x, y, dims, pad, pad_top, head, strip rows); a struct would not clarify the mapping"
)]
pub(crate) fn pixel_to_term_cell(
    x: f64,
    y: f64,
    cw: usize,
    ch: usize,
    rows: u16,
    cols: u16,
    strip_rows: u16,
    pad: usize,
    pad_top: usize,
    head: usize,
) -> (u16, u16) {
    let gx = (x as usize).saturating_sub(pad);
    // X insets by `pad`; Y insets by the (possibly tighter) top pad + head, so a
    // click maps to the same cell the grid renders at `grid_top = pad_top + head`.
    let gy = (y as usize).saturating_sub(pad_top + head);
    let strip_px = strip_rows as usize * ch.max(1);
    let term_y = gy.saturating_sub(strip_px);
    let col = (gx / cw.max(1)).min(cols.saturating_sub(1) as usize) as u16;
    let row = (term_y / ch.max(1)).min(rows.saturating_sub(1) as usize) as u16;
    (row, col)
}

/// Pure "is this pixel in the tab strip, and if so which strip column?" (the body
/// of [`App::strip_col_at`], extracted for unit tests). The chrome `head` band and
/// the interior `pad` border are removed from `y` (and `pad` from `x` — the strip
/// lives inside the pad, below the headroom) first, then `None` when the inset `y`
/// is at/below the strip's pixel height (`strip_rows * ch`) — i.e. in the terminal
/// region. A click in the top `head + pad` band over the strip still maps to the
/// strip (gy saturates to 0). `pad == 0` && `head == 0` is byte-identical.
#[allow(
    clippy::too_many_arguments,
    reason = "pure pixel->strip-column geometry over independent scalar inputs (x, y, dims, pad, pad_top, head, strip rows); a struct would not clarify the mapping"
)]
pub(crate) fn strip_col_for_pixel(
    x: f64,
    y: f64,
    cw: usize,
    ch: usize,
    cols: u16,
    strip_rows: u16,
    pad: usize,
    pad_top: usize,
    head: usize,
) -> Option<u16> {
    let gx = (x as usize).saturating_sub(pad);
    let gy = (y as usize).saturating_sub(pad_top + head);
    let strip_px = strip_rows as usize * ch.max(1);
    if gy >= strip_px {
        return None;
    }
    Some((gx / cw.max(1)).min(cols.saturating_sub(1) as usize) as u16)
}

/// Selection-drag autoscroll: given the pointer's raw window pixel `y`, the
/// interior `pad`, the tab-strip height (`strip_rows * ch`), the cell height `ch`
/// and the terminal `rows`, return how many scrollback lines to move so a drag
/// past a viewport edge extends the selection off screen. Positive scrolls toward
/// older history (above the top edge), negative toward the live bottom, `0` means
/// inside the grid. The magnitude is one line per cell height of overshoot (min
/// 1). Pure, for unit tests.
pub(crate) fn selection_autoscroll_lines(
    y: f64,
    pad: usize,
    strip_px: usize,
    ch: usize,
    rows: u16,
) -> i32 {
    let ch = ch.max(1);
    let top = (pad + strip_px) as f64; // first device pixel of terminal row 0
    let bottom = top + (rows as usize * ch) as f64; // one past the last terminal row
    if y < top {
        // Above the top edge → scroll into history. One line per cell-height of
        // overshoot (min 1), so the further out, the faster.
        autoscroll_step(top - y, ch)
    } else if y >= bottom {
        // Below the bottom edge → scroll toward the live bottom (negative offset).
        -autoscroll_step(y - bottom, ch)
    } else {
        0
    }
}

/// Step count for a drag held `overshoot` device pixels past a grid edge: one
/// line per cell height, minimum one. Both callers hand it a non-negative
/// distance (each branch tests the edge it subtracts).
///
/// SATURATING. The overshoot descends from a raw pointer coordinate, and a drag
/// that leaves the window is reported in whatever space the windowing system
/// pleases — nothing bounds it to the window's own extent. A wrapped `i32` would
/// not merely scroll a wrong distance, it would flip the SIGN and reverse the
/// gesture's DIRECTION, so the magnitude pins instead.
fn autoscroll_step(overshoot: f64, ch: usize) -> i32 {
    (overshoot / ch.max(1) as f64 + 1.0).min(i32::MAX as f64) as i32
}

/// Shift the composed frame `dst` down by `strip_rows.len()` rows and prepend
/// those tab-strip rows, keeping every per-row vector (`cells`, `clusters`,
/// `combining`, `images`, `line_sizes`, `line_size_spans`, `default_bg_spans`)
/// aligned and moving the cursor and row count with the content. Pure (the
/// body of [`App::splice_tab_strip`]'s mutation); an empty `strip_rows` is a
/// no-op. `cell_h` shifts the grid streams' pixel quads with the grid.
///
/// Window-space effect streams (`fire_patch`, `cursor_glow_add`, `glow_under`,
/// `glow_halo`) are already window-absolute, so only their damage row tags
/// move. `grid_top` is the window's `pad + head`; a quad above terminal row 0's
/// top pins its tag to composed row 0.
///
/// `strip_rows` is borrowed (the caller's row cache survives), and each
/// container shifts with one `splice`. `pool` is the resident strip-row buffer
/// pool: each cell row pops a reclaimed buffer and `clone_from`s into it (no
/// fresh allocation after warmup; an empty pool falls back to `clone`).
pub(crate) fn prepend_strip_rows(
    dst: &mut RenderInput,
    strip_rows: &[Vec<RenderCell>],
    cell_h: usize,
    grid_top: usize,
    pool: &mut Vec<Vec<RenderCell>>,
) {
    prepend_strip_row_slices(
        dst,
        strip_rows.len(),
        strip_rows.iter().map(Vec::as_slice),
        cell_h,
        grid_top,
        pool,
    );
}

/// The chrome bleed's per-row gutter tones for the message band's METERED
/// rows (ruling 55) — the renderer's (`aterm_render::band`, design ruling 331).
pub(crate) use aterm_render::band::band_row_edges;

/// [`prepend_strip_rows`] over BORROWED rows: `strip` is how many `strip_rows`
/// yields, so a caller stacking a row from one cache above rows from another
/// (the presence row over the bar rows) passes both without collecting them
/// into a fresh `Vec` per frame.
pub(crate) fn prepend_strip_row_slices<'a>(
    dst: &mut RenderInput,
    strip: usize,
    strip_rows: impl Iterator<Item = &'a [RenderCell]>,
    cell_h: usize,
    grid_top: usize,
    pool: &mut Vec<Vec<RenderCell>>,
) {
    // The engine's one splice (design ruling 331): the native window's
    // producers already place their window-space streams below the chrome
    // rows, so their pixels ride untouched and only the tags move.
    dst.prepend_host_rows(
        strip,
        strip_rows,
        cell_h,
        grid_top,
        pool,
        aterm_core::render::HostRowPixels::Placed,
    );
}

/// Shrink one frame-space selection clip so an overlay band's rows are excluded,
/// or `None` when one rectangle cannot express the remainder.
///
/// The clip is one rectangle, so the complement of the band is only expressible
/// when the band meets an edge of the clip — which is the real shape: the config
/// notice and the find bar are edge bands. A band strictly interior to the
/// selection cannot be excised by a rectangle, so that case fails safe and the
/// caller drops the selection. Erring toward "not painted" is right: a highlight
/// shown over chrome would claim the chrome's text is selected.
fn narrow_clip_below_band(
    clip: aterm_core::render::SelectionClip,
    rows: &std::ops::Range<usize>,
) -> Option<aterm_core::render::SelectionClip> {
    let band_covers_top = rows.start <= clip.row_start && rows.end > clip.row_start;
    let band_covers_bottom = rows.start < clip.row_end && rows.end >= clip.row_end;
    // The band swallows the whole clip: nothing of the selection is visible.
    if band_covers_top && band_covers_bottom {
        return None;
    }
    let narrowed = if band_covers_top {
        aterm_core::render::SelectionClip::new(rows.end, clip.row_end, clip.col_start, clip.col_end)
    } else if band_covers_bottom {
        aterm_core::render::SelectionClip::new(
            clip.row_start,
            rows.start,
            clip.col_start,
            clip.col_end,
        )
    } else {
        // Strictly interior — not expressible as one rectangle.
        return None;
    };
    (narrowed.row_start < narrowed.row_end).then_some(narrowed)
}

/// Declare `band`, the frame rows a chrome splice just overwrote, for the frame
/// being composed: the write half of [`crate::WindowState::chrome_rows`], whose
/// doc carries the contract.
///
/// Stored in terminal rows, translated here: every band splice runs after the
/// tab-strip prepend, so `cells` is `strip` chrome rows then the terminal band,
/// while between frames `input_scratch` may hold either shape. It saturates
/// because a top-edge band (the paste confirmation) may start on the strip's
/// own rows. Empty bands are not recorded.
fn claim_chrome_rows(ws: &mut crate::WindowState, band: std::ops::Range<usize>) {
    let strip = ws
        .input_scratch
        .cells
        .len()
        .saturating_sub(usize::from(ws.rows));
    let band = band.start.saturating_sub(strip)..band.end.saturating_sub(strip);
    if !band.is_empty() {
        ws.chrome_rows.push(band);
    }
}

/// Does any band declared this frame cover terminal row `row`? The read half of
/// [`crate::WindowState::chrome_rows`]. Linear over a list that holds one entry
/// per band on screen — never more than a handful, and empty on the frames that
/// carry no chrome at all.
fn chrome_owns_terminal_row_of(ws: &crate::WindowState, row: usize) -> bool {
    ws.chrome_rows.iter().any(|band| band.contains(&row))
}

/// Remove every host-owned overlay whose painted extent intersects a frame-row
/// replacement band.
///
/// Find/config bars overwrite terminal cells late in the frame, but overlays
/// render in later z-passes than cell glyphs. Clearing only clusters/images
/// therefore lets the cursor, selection tint, an old trail, cat, nova, rain
/// sprite, or glow paint over the chrome that claims the band. Row-tagged
/// streams obey the renderer's single-row-band invariant; jittered word
/// decorations and rowless free sprites use their real signed pixel extents.
fn scrub_overlay_row_band(input: &mut RenderInput, rows: std::ops::Range<usize>, cell_h: usize) {
    if rows.start >= rows.end {
        return;
    }
    // A replacement band also takes custody of pixel-resolution chrome.
    // Retire only covered rasters; an uncovered meter keeps its ground/rail.
    input
        .chrome_rasters
        .retain(|raster| !rows.contains(&usize::from(raster.row)));
    let start16 = u16::try_from(rows.start).unwrap_or(u16::MAX);
    let end16 = u16::try_from(rows.end).unwrap_or(u16::MAX);
    let tagged = |row: u16| row >= start16 && row < end16;
    let y0 = i64::try_from(rows.start.saturating_mul(cell_h)).unwrap_or(i64::MAX);
    let y1 = i64::try_from(rows.end.saturating_mul(cell_h)).unwrap_or(i64::MAX);
    let cell_h_i64 = i64::try_from(cell_h).unwrap_or(0);

    if input.cursor_visible && rows.contains(&input.cursor_row) {
        input.cursor_visible = false;
    }
    // Selection is folded into the renderer's background/glyph passes, so the
    // clip rectangle each selection carries is the only mask. Narrow rather than
    // erase: shrink the frame-space clip so the band's rows are excluded and
    // every other row keeps painting, so the highlight matches what ⌘-C copies.
    //
    // Per selection: a composed split carries one entry per selected pane, and
    // the band may meet one pane's clip at an edge (narrowable) and land inside
    // another's (not narrowable), so the fail-safe drop below costs at most one
    // pane's highlight. The renderer's own per-cell predicate decides which
    // selections the band touches.
    let mut scalar_intersects = false;
    let mut entry_intersects = vec![false; input.selections.len()];
    if input.any_selection() {
        // Stop as soon as every selection that COULD be hit has been accounted for —
        // the `any()` short-circuit the scalar scan this replaced always had.
        //
        // Seeded from the entries whose clip rows actually reach the band, not from
        // the entry count. An entry whose pane box does not touch these rows can
        // never be hit inside them, so counting it leaves `undecided` permanently
        // above zero and the scan runs the full band x cols x entries product on
        // every frame the chrome is up. That is the COMMON case: the find bar and
        // the config notice are top-edge bands, so in a left/right split only the
        // panes touching the top rows are reachable at all.
        let mut undecided = input
            .selections
            .iter()
            .filter(|entry| entry.clip.row_start < rows.end && entry.clip.row_end > rows.start)
            .count();
        if input.selections.is_empty() {
            undecided = 1;
        }
        if undecided == 0 {
            // Nothing reachable — the band cannot touch any selection.
            return;
        }
        let cols = input.cols.min(usize::from(u16::MAX) + 1);
        'band: for frame_row in rows.clone() {
            let row_cells = input.cells.get(frame_row).map(Vec::as_slice).unwrap_or(&[]);
            for col in 0..cols {
                let is_wide_lead = row_cells.get(col + 1).is_some_and(|cell| cell.wide);
                let is_wide_continuation = row_cells.get(col).is_some_and(|cell| cell.wide);
                let Some(hit) =
                    input.selection_hit(frame_row, col, is_wide_lead, is_wide_continuation)
                else {
                    continue;
                };
                let first = match entry_intersects.get_mut(hit) {
                    Some(slot) => !std::mem::replace(slot, true),
                    None => !std::mem::replace(&mut scalar_intersects, true),
                };
                if first {
                    undecided -= 1;
                    if undecided == 0 {
                        break 'band;
                    }
                }
            }
        }
    }
    if scalar_intersects {
        // Intersect with any clip already present (a split pane's), never overwrite
        // it — dropping a pane clip here would let this pane's selection tint a
        // sibling for as long as the chrome is up.
        let clip = input.selection_clip.unwrap_or_else(|| {
            aterm_core::render::SelectionClip::new(0, input.rows, 0, input.cols)
        });
        match narrow_clip_below_band(clip, &rows) {
            Some(clip) => input.selection_clip = Some(clip),
            None => {
                input.selection = aterm_core::selection::TextSelection::new();
                input.selection_clip = None;
            }
        }
    }
    if entry_intersects.iter().any(|&hit| hit) {
        // Retain-in-place: `swap(kept, i)` with `kept <= i` preserves the entry
        // order the renderer's first-hit scan and the damage key both read.
        let mut kept = 0;
        for (i, &intersects) in entry_intersects.iter().enumerate() {
            if intersects {
                match narrow_clip_below_band(input.selections[i].clip, &rows) {
                    Some(clip) => input.selections[i].clip = clip,
                    // Strictly interior to this pane's box — not expressible as one
                    // rectangle, so this pane's highlight fails safe and drops. Its
                    // siblings' entries are untouched.
                    None => continue,
                }
            }
            input.selections.swap(kept, i);
            kept += 1;
        }
        input.selections.truncate(kept);
        if kept == 0 {
            // The list emptied. With `selections` empty, `selection_row_key` and
            // the per-cell predicate fall back to the scalar, which a composed
            // frame stamps as a duplicate of the focused pane's entry, just
            // dropped; clear it too, or it would resurrect that highlight across
            // the chrome.
            input.selection = aterm_core::selection::TextSelection::new();
            input.selection_clip = None;
        }
    }
    input
        .cursor_trail
        .retain(|trail| !rows.contains(&trail.row));
    input.char_fg.retain(|cell| !tagged(cell.row));
    input.fire_halo.retain(|cell| !tagged(cell.row));
    input.cursor_glow_add.retain(|quad| !tagged(quad.row));
    input.glow_under.retain(|quad| !tagged(quad.row));
    input.fire_patch.retain(|quad| !tagged(quad.row));
    input.glow_halo.retain(|quad| !tagged(quad.row));
    input.ink.retain(|cell| !tagged(cell.row));
    input.word_decorations.retain(|decoration| {
        let top = i64::from(decoration.row)
            .saturating_mul(cell_h_i64)
            .saturating_add(i64::from(decoration.dy));
        let bottom = top.saturating_add(cell_h_i64);
        bottom <= y0 || top >= y1
    });
    input.nova_add.retain(|quad| !tagged(quad.row));
    input.cat_quads.retain(|quad| !tagged(quad.row));
    input.rain_quads.retain(|quad| !tagged(quad.row));
    input.rain_add.retain(|quad| !tagged(quad.row));
    input.free_sprites.retain(|sprite| {
        let top = i64::from(sprite.y);
        let bottom = top.saturating_add(i64::from(sprite.h));
        bottom <= y0 || top >= y1
    });

    // An atlas without surviving quads is semantically inert. Dropping the Arc
    // also prevents a replaced top band from retaining obsolete capture assets.
    if input.cat_quads.is_empty() {
        input.cat_atlas = None;
    }
    if input.free_sprites.is_empty() {
        input.free_atlas = None;
    }
    if input.rain_quads.is_empty() {
        input.rain_atlas = None;
    }
}

#[cfg(test)]
mod overlay_scrub_selection_tests {
    use super::*;
    use aterm_core::selection::{SelectionSide, SelectionType};

    #[test]
    fn scrub_detects_block_selection_snapped_onto_wide_lead() {
        let blank = crate::chrome_band::blank_cell(aterm_render::Theme::default());
        let mut continuation = blank;
        continuation.wide = true;

        let mut input = RenderInput::empty();
        input.rows = 1;
        input.cols = 1;
        // Keep the continuation just outside the declared frame width. The
        // renderer still consults it to classify column zero as a wide lead.
        input.cells = vec![vec![blank, continuation]];
        input
            .selection
            .start_selection(0, 1, SelectionSide::Left, SelectionType::Block);
        input.selection.update_selection(0, 1, SelectionSide::Right);
        input.selection.complete_selection();
        assert!(
            input.selection_contains_cell(0, 0, true, false),
            "negative-control precondition: wide snapping reaches the visible lead"
        );
        assert!(
            !input.selection_contains_cell(0, 0, false, false),
            "a scalar-only probe would miss this intersection"
        );

        scrub_overlay_row_band(&mut input, 0..1, 16);

        assert!(
            !input.selection.has_selection(),
            "chrome replacement must scrub the same wide-aware selection the renderer paints"
        );
    }
}

/// Decide whether the native host must extract an authoritative live grid
/// snapshot for rain. Literal-mode sampling is independent of the damage
/// epoch so a classic-to-literal config reload cannot wait for unrelated PTY
/// output before the on-screen alphabet becomes real.
fn rain_refresh_needed(
    enabled: bool,
    suspended: bool,
    sync_hold: bool,
    display_offset: usize,
    engine: Option<&crate::matrix_rain::MatrixRain>,
    epoch: u64,
) -> bool {
    enabled
        && !suspended
        && !sync_hold
        && display_offset == 0
        && engine.is_none_or(|e| e.needs_rescan(epoch) || e.needs_material_sample())
}

/// Effect-only reuse: may this frame present `scratch` unchanged, skipping the
/// terminal-mutex grid extraction? Effect animation ticks owe a present every
/// frame while typing, and re-extracting an unchanged grid for each costs CPU
/// and battery, not latency.
///
/// Sound only if a refill would reproduce the snapshot exactly
/// (`cell_frame_fill` restamps every channel, not just cells). The clauses:
///
/// * `uncontended`: the hold came from `term_try_lock`, not a writer mid-batch.
/// * `!term.has_damage()`: nothing unconsumed.
/// * `snapshot_seq == live_epoch`: stamped at the current damage session.
/// * `engine_fill_seq == snapshot_seq`: no host mutator (fade, IME preedit,
///   ghosts, band splice) wrote cells since the fill.
/// * `process_sequence` match: no parser batch since the fill (catches cursor
///   moves, OSC 10/11/12, DECTCEM, image placements the damage tracker misses).
/// * `selection` match: the one state a host changes with neither damage nor a
///   batch (`text_selection_mut`).
/// * identity, alt screen, dims, `row_shift`, `display_offset`, `base_y`,
///   `absolute_row_revision`: the same continuity clauses as
///   `Terminal::damage_scoped_refill_refusal`.
///
/// The caller also refuses a tab-strip window (`strip_rows_n > 0`):
/// `undo_host_row_prepend` leaves an intermediate, not a presentable frame. Any
/// `false` falls through to the normal extract + damage consume, and a skip
/// consumes no damage because there is none.
fn effect_only_snapshot_reusable(
    uncontended: bool,
    scratch: &RenderInput,
    term: &Terminal,
    live_epoch: u64,
    rows: usize,
    cols: usize,
) -> bool {
    uncontended
        && !term.has_damage()
        && scratch.snapshot_seq == live_epoch
        && scratch.engine_fill_seq == scratch.snapshot_seq
        && scratch.process_sequence == term.pipeline_timestamps().process_sequence
        && scratch.terminal_id != 0
        && scratch.terminal_id == term.render_identity()
        && scratch.engine_alt == term.is_alternate_screen()
        && scratch.row_shift == 0
        && scratch.rows == rows
        && scratch.cols == cols
        && scratch.cells.len() == rows
        && rows == usize::from(term.rows())
        && cols == usize::from(term.cols())
        // A viewport parked in history reuses like the live bottom when it is
        // the same viewport: the clauses above prove nothing moved (a
        // `scroll_display` marks damage, the output pin/re-pin is a batch, same
        // `base_y`), so equal offsets mean the same absolute anchor. A scratch
        // from another offset is refused.
        && i64::from(scratch.display_offset)
            == i64::try_from(term.grid().display_offset()).unwrap_or(i64::MAX)
        && scratch.base_y == i64::try_from(term.grid().base_y()).unwrap_or(i64::MAX)
        && scratch.absolute_row_revision == term.absolute_row_revision()
        && scratch.selection == *term.text_selection()
}

#[cfg(test)]
#[path = "app_render_effect_only_reuse_tests.rs"]
mod effect_only_reuse_tests;

/// Maintain the phosphor hidden-cursor band (design §6): the resident ring of
/// the last [`crate::matrix_rain::HIDDEN_CURSOR_BAND_ROWS`] recently-damaged
/// viewport rows, most recent first. When DECTCEM hides the cursor, Ink parks
/// it at a meaningless position — damage recency stands in for it, and the
/// band is where Claude Code's inline input box actually lives. Must run
/// under the terminal lock before the frame's `take_damage` (damage is gone
/// after). A full-damage frame (resize / alt-swap / first frame) locates
/// nothing — every row is "damaged" — so it leaves the ring unchanged rather
/// than flooding it with arbitrary rows. In-place on the resident ring: no
/// per-frame allocation once the ring reaches capacity.
pub(crate) fn update_rain_hidden_band(
    band: &mut Vec<u16>,
    dmg: &aterm_core::grid::damage::Damage,
    rows: usize,
) {
    if dmg.is_full() {
        return;
    }
    let rows = u16::try_from(rows).unwrap_or(u16::MAX);
    for r in dmg.damaged_rows(rows) {
        // Promote to most-recent-first; ascending iteration means the frame's
        // Bottom-most damaged rows end up at the ring's head (the §6 bottom-
        // region bias).
        if let Some(p) = band.iter().position(|&x| x == r) {
            band.remove(p);
        }
        band.insert(0, r);
        band.truncate(crate::matrix_rain::HIDDEN_CURSOR_BAND_ROWS);
    }
}

pub(crate) use aterm_effects::pane::PanePlace;

// The verdict: a command's exit code from the shell's OSC 133/633 `D`, with its
// authenticated exit status and duration. The pet feels it, the music box says
// it, and the rainbow prices the next key by it.
//
// Armed by the keyed Enter, spent by the first `D`: the arm is the session's
// accepted plain-Enter turn boundary (`OutputEchoTracker`: a real key or raw
// editor bytes ending in a newline, as `aterm ctl send` produces). A `D` with
// no armed Enter is silent, so program output never speaks.

/// A command must have RUN this long before its success is worth saying
/// anything about — the same two seconds that separate "the shell answered"
/// from "the machine worked" everywhere else in the companion family
/// (`kitty_pet`'s `CHEER_MIN_MS`). Under it: nothing at all.
const VERDICT_MIN_MS: u64 = 2_000;
/// …and this long before it was a BUILD: the faraway ice bell rings over the
/// cadence, and the next key you type is born hot (`kitty_pet`'s
/// `CHEER_BIG_MS`, `rainbow_kitty::spine::VERDICT_WINDOW_S`).
const VERDICT_ICE_MS: u64 = 30_000;

/// **the ARM**, as a pure function of the window's spend latch and the
/// session's last accepted plain-Enter turn boundary: `true` iff this `D` was
/// run by a keystroke — and the arm is spent by the answer, whatever the
/// answer turns out to be.
///
/// It is the boundary's own stamp that is spent, not a counter, so the three
/// ways a `D` can arrive with no keystroke behind it all fall out of one
/// comparison: a program that emits the marks itself and a shell restoring a
/// session's history carry no newer boundary; a second `D` for one Enter
/// carries the boundary already spent; and a fresh window that has never seen
/// an Enter carries `None`.
pub(crate) fn verdict_armed(
    spent: &mut Option<(u64, std::time::Instant)>,
    session: u64,
    boundary: Option<std::time::Instant>,
) -> bool {
    let Some(at) = boundary else {
        return false;
    };
    if *spent == Some((session, at)) {
        return false;
    }
    *spent = Some((session, at));
    true
}

/// Spend one keyed completion in either layout and feed an explicitly armed
/// celebration on success. The return value is the existing verdict admission,
/// so its sound and the celebration share one Enter rather than separate latches.
/// Failed commands consume the boundary too; a later unkeyed success cannot use it.
fn keyed_celebration_completion(
    sing: &mut aterm_effects::kitty_sing::KittySing,
    spent: &mut Option<(u64, std::time::Instant)>,
    session: u64,
    boundary: Option<std::time::Instant>,
    now: std::time::Instant,
    code: i32,
) -> bool {
    let keyed = verdict_armed(spent, session, boundary);
    if keyed && code == 0 {
        sing.note_green_block(now, session);
    }
    keyed
}

/// What the verdict does with one `D`, as a pure function of the facts the
/// shell handed over:
///
/// * `None`: say nothing (a success under [`VERDICT_MIN_MS`]).
/// * `Some((failed, ice))`: sound the verdict; `ice` adds the bell, only for a
///   successful command past [`VERDICT_ICE_MS`].
///
/// A failure always speaks, however fast.
pub(crate) fn verdict_voice(failed: bool, dur_ms: Option<u64>) -> Option<(bool, bool)> {
    let dur = dur_ms.unwrap_or(0);
    if failed {
        return Some((true, false));
    }
    (dur >= VERDICT_MIN_MS).then_some((false, dur >= VERDICT_ICE_MS))
}

/// The resident pet's frame grid in the host contract's terms: the cursor
/// effects' cell metrics and this surface's extent (the window grid, or the
/// focused pane's), clamped to `u16`, with the grid's `(0, 0)` at `origin_px`
/// in frame pixels (the effects origin, plus the pane's own on a split).
pub(crate) fn pet_frame_geom(
    cell: (usize, usize),
    grid: (usize, usize),
    origin_px: (i32, i32),
) -> aterm_effects::host::FrameGeom {
    let clamp = |v: usize| v.min(usize::from(u16::MAX)) as u16;
    aterm_effects::host::FrameGeom {
        rows: clamp(grid.0),
        cols: clamp(grid.1),
        cell_w: clamp(cell.0),
        cell_h: clamp(cell.1),
        origin_px,
    }
}

/// The window's presentability as the pet owner reads it. A native window never
/// reports `Hidden` per frame: its presentability edge retires the pet's
/// coordinates in `lib.rs`, and an overlay is `PetFacts::obscured`.
pub(crate) fn pet_visibility(focused: bool) -> aterm_effects::host::Visibility {
    if focused {
        aterm_effects::host::Visibility::Focused
    } else {
        aterm_effects::host::Visibility::VisibleUnfocused
    }
}

/// The room's facts: what the resident pet is told about its session on a frame
/// the host is already drawing, noted through the `note_*` idiom (never a light
/// or a wake). One projection for both render arms, so a split tells the pet
/// the same room a single pane does.
///
/// * (a) the lease: `SessionCtx::turn_lease` live at `now_us`
///   ([`crate::Lease::is_live`]), the seam `who` reads, without allocating;
/// * (b) quiet: the status observer's phase
///   ([`crate::session_status::Phase::Quiet`]);
/// * (c) the turn: the newest [`crate::turn_ledger::TurnRecord`]'s id and
///   settle verdict (the pet diffs the id);
/// * (d) the sibling: the caret of a sibling pane streaming this frame, in the
///   pet's pane cells (`None` in a single pane or when no sibling talks);
/// * (e) the inbox: [`crate::fabric::SessionFabric::room_facts`].
///
/// Each read is a short leaf lock taken after the frame hold is released (the
/// same locks `who`/`turns`/`inbox` take), so no lock edge is added. A session
/// the pool no longer holds reports only "nobody is driving".
fn room_facts(
    session: Option<&crate::Session>,
    status: Option<&crate::session_status::Status>,
    sibling: Option<(f32, f32)>,
) -> aterm_effects::companion::RoomFacts {
    aterm_effects::companion::RoomFacts {
        quiet: status.is_some_and(|s| s.phase == crate::session_status::Phase::Quiet),
        sibling,
        session: session.map(|session| {
            let ctx = &session.ctx;
            let now_us = crate::metrics::now_us();
            let lease = ctx
                .turn_lease
                .lock()
                .unwrap_or_else(|p| p.into_inner())
                .as_ref()
                .is_some_and(|l| l.is_live(now_us));
            let turn = {
                let turns = ctx.turns.lock().unwrap_or_else(|p| p.into_inner());
                match turns.high_id() {
                    // `since(id − 1)` is the suffix at `id` exactly (ids are
                    // unique and strictly increasing), i.e. the newest record.
                    Some(id) => (
                        id,
                        turns
                            .since(Some(id.saturating_sub(1)))
                            .next()
                            .is_some_and(|r| r.status == "settled"),
                    ),
                    None => (0, false),
                }
            };
            let (unseen, overdue, hold) = ctx.fabric.room_facts(crate::turn_ledger::now_ms());
            aterm_effects::companion::SessionRoom {
                lease,
                turn,
                inbox: aterm_effects::kitty_pet::RoomInbox {
                    unseen,
                    overdue,
                    hold,
                },
            }
        }),
    }
}

/// The sing-along's once-per-bar riff gesture, shared by both render paths.
/// `sig` is the held character's song signature (`KittySing::signature`), from
/// which the synth derives the verse, root transpose and mode rotation, so a
/// different key sings a different verse over one continuous bar grid.
fn sing_riff_event(bar: u64, gain: f32, sig: u32) -> aterm_effects::trail_sound::SoundEvent {
    aterm_effects::trail_sound::SoundEvent {
        style: crate::cursor_glow::GlowStyle::RainbowKitty,
        // The sing-along riff is its own authored song — the
        // `trail_sound_style` override never re-voices it.
        voice: aterm_effects::trail_sound::SoundVoice::Style,
        kind: aterm_effects::trail_sound::SoundGesture::Celebration(
            // Through the stable constructor (not the variant literal).
            aterm_effects::trail_sound::CelebrationGesture::riff_bar((bar & 0xffff) as u16, sig),
        ),
        pan: 0.0,
        // Momentum is pinned to 1.0 while armed — that is maximal flow; the
        // riff warms accordingly.
        heat: 1.0,
        hue: 0.0,
        gain,
        // Tone-blind like the bonk, and it never feeds the bed.
        tone: aterm_effects::tone::Tone::Technical,
        bed: false,
        shifted: false, // an authored riff bar, not a keystroke
    }
}

/// The outro's sound event (§27): the armed celebration's ending in the run's
/// own key — pushed once, on the last bar line, under the riff's own gain law
/// ([`sing_riff_gain`]), so a quieted riff has a quiet ending.
fn sing_outro_event(gain: f32, sig: u32) -> aterm_effects::trail_sound::SoundEvent {
    aterm_effects::trail_sound::SoundEvent {
        kind: aterm_effects::trail_sound::SoundGesture::Celebration(
            aterm_effects::trail_sound::CelebrationGesture::outro(sig),
        ),
        ..sing_riff_event(0, gain, sig)
    }
}

/// Whether the Sparkle Words engine may present (spend births rather than bank
/// them): the window's un-woken motion focus (`App::motion_focus`: raw focus or
/// the recording pin), never the typed wake, and not suspended. The typed wake
/// wakes the cursor companion only; waking the words on it would flap them on
/// every typing gap. One predicate for the single-pane and composed passes
/// (owner, 2026-09-25).
#[must_use]
pub(crate) fn sparkle_words_presentable(word_focus: bool, suspended: bool) -> bool {
    word_focus && !suspended
}

