#[derive(Clone, Copy)]
struct ComposedOutputStreakConfig {
    enabled: bool,
    intensity: f32,
    tail: u16,
    max_streaks: u8,
    idle_secs: f32,
    sound_gain: Option<f32>,
    style: crate::cursor_glow::GlowStyle,
    voice: aterm_effects::trail_sound::SoundVoice,
    animate: bool,
    now: Instant,
}

/// Whether a host route must drop Prism Wake before allocating an engine or
/// inspecting frame cells. `suppressed` is route-local alt/history policy.
#[must_use]
pub(crate) const fn output_streak_inert(
    enabled: bool,
    animate: bool,
    intensity: f32,
    suppressed: bool,
) -> bool {
    !enabled || !animate || intensity <= 0.0 || suppressed
}

impl ComposedOutputStreakConfig {
    /// Global reset conditions. Check these before touching any pane so an
    /// inert policy neither allocates engines nor scans resident cells.
    fn inert(self) -> bool {
        output_streak_inert(self.enabled, self.animate, self.intensity, false)
    }
}

#[derive(Clone, Copy)]
struct ComposedOutputStreakPane {
    session: u64,
    slot: usize,
    place: PanePlace,
    may_speak: bool,
    echo: crate::app_input::OutputEchoSample,
}

/// Fold one pane's engine frame with where those pixels land. Exact engine
/// rest stays exact zero; otherwise divider moves and pane reorderings change
/// the repaint key even when the pane-local animation sample is unchanged.
fn placed_output_streak_fp(
    pane_fp: u64,
    pane: ComposedOutputStreakPane,
    paint_index: usize,
) -> u64 {
    if pane_fp == 0 {
        return 0;
    }
    let mut placement = aterm_effects::genome::mix(pane.session);
    for value in [
        u64::from(pane.place.row_off),
        u64::from(pane.place.col_off),
        u64::from(pane.place.rows),
        u64::from(pane.place.cols),
    ] {
        placement = aterm_effects::genome::mix(placement ^ value);
    }
    aterm_effects::genome::mix(pane_fp ^ placement).rotate_left((paint_index % 64) as u32)
}

/// Tick and place one coherent pane snapshot through the pipeline
/// ([`aterm_effects::pipeline::EffectsPipeline::streak_pane`]), sounding its
/// cue through the resolved gain. Both the pure-terminal split and the
/// heterogeneous compositor route through this function, so geometry,
/// suppression, audio mapping, and channel co-residency cannot drift.
fn tick_composed_output_streak_pane(
    fx: &mut aterm_effects::pipeline::EffectsPipeline,
    into: aterm_effects::pipeline::NovaInto<'_>,
    snapshot: &RenderInput,
    content_seq: u64,
    pane: ComposedOutputStreakPane,
    resolved: ComposedOutputStreakConfig,
) -> (u64, Option<aterm_effects::trail_sound::SoundEvent>) {
    let speaks = pane.may_speak && resolved.sound_gain.is_some();
    let (fp, cue) = fx.streak_pane(
        &aterm_effects::pipeline::StreakPane {
            session: pane.session,
            slot: pane.slot,
            place: pane.place,
            echo: pane.echo.streak(),
            snapshot,
            content_seq,
            sound: speaks,
        },
        aterm_effects::pipeline::StreakKnobs {
            now: resolved.now,
            intensity: resolved.intensity,
            tail: resolved.tail,
            max_streaks: resolved.max_streaks,
            idle_secs: resolved.idle_secs,
        },
        into,
    );
    let sound = cue.and_then(|cue| {
        resolved
            .sound_gain
            .map(|gain| aterm_effects::trail_sound::SoundEvent {
                style: resolved.style,
                voice: resolved.voice,
                kind: aterm_effects::trail_sound::SoundGesture::Output(cue.sound.output_gesture()),
                pan: cue.pan,
                heat: 0.0,
                hue: cue.hue,
                gain,
                shifted: false,
                tone: aterm_effects::tone::Tone::Technical,
                bed: false,
            })
    });
    (fp, sound)
}

/// Everything the composed sparkle pass needs that `redraw_compose` already
/// resolved: the visible panes, the window grid + cell metrics, the focused
/// pane's caret, and this frame's companion decision.
pub(crate) struct ComposeDecoCtx<'a> {
    pub(crate) panes: &'a [(pane::PaneRect, Arc<Mutex<Terminal>>)],
    pub(crate) focus: u64,
    /// Canonical focused-view slot. Session identity is insufficient because
    /// two visible views may mirror one terminal session.
    pub(crate) focus_index: usize,
    pub(crate) win_rows: u16,
    pub(crate) win_cols: u16,
    pub(crate) cell_w: u32,
    pub(crate) cell_h: u32,
    /// The focused pane's caret in pane-local cells; `None` while scrolled into
    /// history or hidden.
    pub(crate) focus_cursor: Option<(u16, u16)>,
    /// The window focus the cursor effects fold: `App::cursor_fx_focus` (raw
    /// focus, recording pin, typed wake) on the live present; raw focus on a
    /// capture splice.
    pub(crate) win_focused: bool,
    /// The UN-woken focus (`App::motion_focus`: raw focus or the recording
    /// pin, no typed wake) — the Sparkle Words presentability input every
    /// pane's `set_presentable` takes ([`sparkle_words_presentable`]).
    pub(crate) word_focus: bool,
    /// Whether the motion policy still animates word sparkles.
    pub(crate) animate_sparkles: bool,
    /// Whether the motion policy still animates Prism Wake's output streak. Its
    /// own term: the streak paints whether or not Sparkle Words is configured.
    pub(crate) animate_streak: bool,
    /// Whether the independent cursor-companion motion policy is animated.
    /// This is deliberately not derived from Sparkle Words config.
    pub(crate) animate_cat: bool,
    /// This frame's companion opacity (0 ⇒ no companion is drawn) and pose.
    pub(crate) kitty_alpha: u8,
    pub(crate) cat_frame: crate::kitty_cursor::CatFrame,
    /// The pet companion's resolved frame, already ticked by its owner for this
    /// pass. Its `on_glass` carries the custody gate, so in pet mode it excludes
    /// the flying face.
    pub(crate) pet: aterm_effects::companion::CompanionFrame,
    /// Whether this composed pass is a drawn present (`redraw_compose`) or a
    /// capture splice (`app_introspect`'s composed arm) re-using the same
    /// deco path. Only a present may spend a hello at the pet sync site —
    /// see [`emit_resident_pet`]; everything else in the pass is
    /// present/capture-agnostic by design.
    pub(crate) present: bool,
    pub(crate) accent: u32,
    pub(crate) cursor_color: u32,
    pub(crate) now: Instant,
}

/// One wallpaper cover-scale generation for one window (see
/// [`crate::WindowState::wallpaper_scaled`]): the admitted asset scaled to the
/// window's exact frame pixel dims, toned toward the theme background, and
/// published as a fresh `SceneAtlas` Arc — the identity every renderer keys
/// its caches (and the damage full-repaint verdict) on.
pub(crate) struct WallpaperScaled {
    fp: u64,
    dim_bits: u32,
    bg: u32,
    w: u32,
    h: u32,
    rows: usize,
    cols: usize,
    atlas: std::sync::Arc<aterm_core::render::SceneAtlas>,
    /// The resolved default foreground the tint pass compared against (the
    /// achromatic-ground fallback keeps it only where it actually reads) —
    /// part of the cache key, like `bg`.
    fg: u32,
    /// Wallpaper text tint: one glyph colour per grid cell, the backdrop's hue
    /// under that cell brightness-flipped per cell and walked to the WCAG 4.5:1
    /// floor. `None` where the ground is too achromatic and the ordinary
    /// foreground already reads. Sampled from the scaled texels, `rows*cols`
    /// entries, row-major.
    tint: Vec<Option<[u8; 3]>>,
}

/// One glyph tint per grid cell, sampled at each cell's center from the
/// scaled backdrop (the picture is smooth at cell granularity, so one texel
/// stands in for the cell; padding offsets are within a cell and immaterial).
fn wallpaper_cell_tints(
    rgba: &[u8],
    w: usize,
    h: usize,
    rows: usize,
    cols: usize,
    fallback_fg: u32,
) -> Vec<Option<[u8; 3]>> {
    let mut out = Vec::with_capacity(rows.saturating_mul(cols));
    if w == 0 || h == 0 || rows == 0 || cols == 0 {
        return out;
    }
    for r in 0..rows {
        let y = ((r * 2 + 1) * h / (rows * 2)).min(h - 1);
        for c in 0..cols {
            let x = ((c * 2 + 1) * w / (cols * 2)).min(w - 1);
            let i = (y * w + x) * 4;
            let px =
                (u32::from(rgba[i]) << 16) | (u32::from(rgba[i + 1]) << 8) | u32::from(rgba[i + 2]);
            out.push(wallpaper_text_tint_color(px, fallback_fg));
        }
    }
    out
}

/// Merge wallpaper-derived default-foreground tints into the frame's existing
/// sorted-unique ink channel. Existing producers win on an occupied cell. The
/// two vectors swap at the end so a steady frame reuses resident allocations.
/// This deliberately does not memoize the cell projection: changed terminal
/// glyphs must be observed, so a tinted present still performs the O(rows*cols)
/// eligibility scan.
fn merge_wallpaper_tint_ink(
    cells: &[Vec<RenderCell>],
    rows: usize,
    cols: usize,
    default_fg: [u8; 3],
    tint: &[Option<[u8; 3]>],
    existing: &mut Vec<aterm_core::render::InkCell>,
    scratch: &mut Vec<aterm_core::render::InkCell>,
) {
    scratch.clear();
    scratch.reserve(existing.len().saturating_add(rows.saturating_mul(cols) / 4));
    let mut ex = existing.iter().copied().peekable();
    for (r, row) in cells.iter().enumerate().take(rows) {
        if r > usize::from(u16::MAX) {
            break;
        }
        for (c, cell) in row.iter().enumerate().take(cols) {
            while ex
                .peek()
                .is_some_and(|entry| (usize::from(entry.row), usize::from(entry.col)) < (r, c))
            {
                scratch.push(ex.next().expect("peeked"));
            }
            if ex
                .peek()
                .is_some_and(|entry| usize::from(entry.row) == r && usize::from(entry.col) == c)
            {
                scratch.push(ex.next().expect("peeked"));
                continue;
            }
            // Blanks paint no glyph; a wide continuation has no lead glyph of
            // its own; non-default foreground keeps its SGR color.
            if cell.ch == ' ' || cell.wide || cell.fg != default_fg || c > usize::from(u16::MAX) {
                continue;
            }
            let Some(color) = tint.get(r * cols + c).copied().flatten() else {
                continue;
            };
            scratch.push(aterm_core::render::InkCell {
                row: r as u16,
                col: c as u16,
                color,
            });
        }
    }
    scratch.extend(ex);
    std::mem::swap(existing, scratch);
}

#[cfg(test)]
mod wallpaper_tint_ink_tests {
    use super::merge_wallpaper_tint_ink;
    use aterm_core::render::InkCell;
    use aterm_core::terminal::{RenderCell, UnderlineStyle};

    fn cell(ch: char, fg: [u8; 3], wide: bool) -> RenderCell {
        RenderCell {
            ch,
            fg,
            bg: [0, 0, 0],
            wide,
            emoji_presentation: false,
            text_presentation: false,
            bold: false,
            italic: false,
            underline: UnderlineStyle::None,
            strikethrough: false,
            overline: false,
            underline_color: None,
            overline_color: None,
            script: aterm_core::terminal::Script::Normal,
        }
    }

    fn tuples(ink: &[InkCell]) -> Vec<(u16, u16, [u8; 3])> {
        ink.iter()
            .map(|entry| (entry.row, entry.col, entry.color))
            .collect()
    }

    #[test]
    fn merge_preserves_precedence_order_and_swaps_warm_allocations() {
        let default_fg = [200, 200, 200];
        let cells = vec![
            vec![
                cell('a', default_fg, false),
                cell('b', default_fg, false),
                cell(' ', default_fg, false),
                cell('c', default_fg, true),
            ],
            vec![
                cell('d', default_fg, false),
                cell('e', [1, 2, 3], false),
                cell('f', default_fg, false),
                cell('g', default_fg, false),
            ],
        ];
        let tint = vec![
            Some([1, 1, 1]),
            Some([2, 2, 2]),
            Some([3, 3, 3]),
            Some([4, 4, 4]),
            Some([5, 5, 5]),
            Some([6, 6, 6]),
            None,
            Some([7, 7, 7]),
        ];
        let producers = vec![
            InkCell {
                row: 0,
                col: 1,
                color: [90, 90, 90],
            },
            InkCell {
                row: 1,
                col: 0,
                color: [80, 80, 80],
            },
            InkCell {
                row: 2,
                col: 0,
                color: [70, 70, 70],
            },
        ];
        let expected = vec![
            (0, 0, [1, 1, 1]),
            (0, 1, [90, 90, 90]),
            (1, 0, [80, 80, 80]),
            (1, 3, [7, 7, 7]),
            (2, 0, [70, 70, 70]),
        ];
        let mut ink = producers.clone();
        let mut scratch = Vec::new();
        let merge = |ink: &mut Vec<InkCell>, scratch: &mut Vec<InkCell>| {
            merge_wallpaper_tint_ink(&cells, 2, 4, default_fg, &tint, ink, scratch);
        };

        merge(&mut ink, &mut scratch);
        assert_eq!(tuples(&ink), expected);

        // Warm both alternating vectors, then prove the next merge merely swaps
        // their allocations. This catches a fresh per-frame merged Vec while
        // remaining independent of the process-global test allocator.
        ink.clear();
        ink.extend_from_slice(&producers);
        merge(&mut ink, &mut scratch);
        ink.clear();
        ink.extend_from_slice(&producers);
        let (ink_allocation, scratch_allocation) = (ink.as_ptr(), scratch.as_ptr());
        let (ink_capacity, scratch_capacity) = (ink.capacity(), scratch.capacity());
        merge(&mut ink, &mut scratch);
        assert_eq!(tuples(&ink), expected);
        assert_eq!(ink.as_ptr(), scratch_allocation);
        assert_eq!(scratch.as_ptr(), ink_allocation);
        assert_eq!(ink.capacity(), scratch_capacity);
        assert_eq!(scratch.capacity(), ink_capacity);
    }
}

/// WCAG contrast ratio between two relative luminances.
fn wcag_contrast(a: f32, b: f32) -> f32 {
    let (hi, lo) = if a > b { (a, b) } else { (b, a) };
    (hi + 0.05) / (lo + 0.05)
}

/// The tint pass guarantees at least this contrast against the backdrop
/// texel under the cell (WCAG AA for normal text). Both poles clear it at
/// every ground luminance, so the walk below always terminates readable.
const WALLPAPER_TINT_CONTRAST_FLOOR: f32 = 4.5;

/// The ground luminance below which white ink out-contrasts black ink
/// (`(1.05)/(L+0.05) >= (L+0.05)/0.05` ⇒ `L <= sqrt(1.05*0.05) - 0.05`).
const LIGHT_INK_BELOW: f32 = 0.179;

/// A "cool but readable" glyph tint for text sitting on `backdrop`: the
/// backdrop's own hue, flipped to whichever brightness pole out-contrasts
/// the ground (light ink over the picture's dark areas, dark ink over its
/// bright ones) and then walked — brightness first, saturation after —
/// until it clears [`WALLPAPER_TINT_CONTRAST_FLOOR`]. The letterforms pick
/// up the image's local color and stay legible no matter how light or dark
/// the picture is at that cell. Near-achromatic ground (grey / washed-out
/// areas) takes no hue — an arbitrary one would read as noise — and keeps
/// the ordinary foreground (`None`) where it already clears the floor, else
/// a plain readable neutral of the winning polarity.
fn wallpaper_text_tint_color(backdrop: u32, fallback_fg: u32) -> Option<[u8; 3]> {
    use aterm_effects::color_math::{hsv2rgb, relative_luminance, rgb2hsv};
    let ground = relative_luminance(backdrop);
    let light_ink = ground <= LIGHT_INK_BELOW;
    let (hue, s, _v) = rgb2hsv(backdrop);
    if s < 0.10 {
        if wcag_contrast(relative_luminance(fallback_fg), ground) >= WALLPAPER_TINT_CONTRAST_FLOOR {
            return None;
        }
        let neutral = if light_ink { 0xF0 } else { 0x20 };
        return Some([neutral, neutral, neutral]);
    }
    let mut sat = (s * 0.9).clamp(0.35, 0.70);
    let mut v = if light_ink { 0.95 } else { 0.34 };
    let mut tinted = hsv2rgb(hue, sat, v);
    // Saturated hues can sit dark even at full brightness (pure blue) or
    // light even quite low (yellow), so push brightness toward the pole,
    // then bleed saturation out — sat 0 at the pole is white/black, whose
    // contrast clears the floor on any ground the polarity choice matched.
    for _ in 0..24 {
        if wcag_contrast(relative_luminance(tinted), ground) >= WALLPAPER_TINT_CONTRAST_FLOOR {
            break;
        }
        if light_ink && v < 1.0 {
            v = (v + 0.06).min(1.0);
        } else if !light_ink && v > 0.0 {
            v = (v - 0.06).max(0.0);
        } else {
            sat = (sat - 0.08).max(0.0);
        }
        tinted = hsv2rgb(hue, sat, v);
    }
    Some([
        ((tinted >> 16) & 0xff) as u8,
        ((tinted >> 8) & 0xff) as u8,
        (tinted & 0xff) as u8,
    ])
}

/// Cover-scale `src` (straight sRGB RGBA8, `sw × sh`) to exactly `dw × dh`
/// (center-crop to the destination aspect, then the shared linear-light
/// `resample_rgba`), composite any translucency over the theme background,
/// tone the result toward it by `dim`, and force every texel opaque — a
/// wallpaper replaces the background-opacity glass, never composites with it.
fn scale_wallpaper_cover(
    src: &[u8],
    sw: usize,
    sh: usize,
    dw: usize,
    dh: usize,
    dim: f32,
    bg: u32,
) -> Vec<u8> {
    let scale = (dw as f64 / sw as f64).max(dh as f64 / sh as f64);
    let crop_w = ((dw as f64 / scale).round() as usize).clamp(1, sw);
    let crop_h = ((dh as f64 / scale).round() as usize).clamp(1, sh);
    let x0 = (sw - crop_w) / 2;
    let y0 = (sh - crop_h) / 2;
    let mut crop = Vec::with_capacity(crop_w * crop_h * 4);
    for y in y0..y0 + crop_h {
        let start = (y * sw + x0) * 4;
        crop.extend_from_slice(&src[start..start + crop_w * 4]);
    }
    let mut out = aterm_render::resample_rgba(&crop, crop_w, crop_h, dw, dh);
    let dim = dim.clamp(0.0, 1.0);
    let bg_rgb = [
        ((bg >> 16) & 0xff) as f32,
        ((bg >> 8) & 0xff) as f32,
        (bg & 0xff) as f32,
    ];
    for px in out.as_chunks_mut::<4>().0 {
        let a = f32::from(px[3]) / 255.0;
        for (i, ground) in bg_rgb.iter().enumerate() {
            let composed = f32::from(px[i]) * a + ground * (1.0 - a);
            let toned = composed * (1.0 - dim) + ground * dim;
            px[i] = toned.round().clamp(0.0, 255.0) as u8;
        }
        px[3] = 255;
    }
    out
}

/// A divider cell for the gaps between split panes: a blank glyph filled with a
/// mid-tone background so the 1-cell line reads as a visible seam regardless of
/// font glyph coverage. The colour is a 50/50 blend of the theme's foreground and
/// background, so it contrasts on both dark and light themes.
pub(crate) fn divider_cell(theme: Theme) -> RenderCell {
    let mix = |shift: u32| {
        let a = ((theme.fg >> shift) & 0xff) as u16;
        let b = ((theme.bg >> shift) & 0xff) as u16;
        ((a + b) / 2) as u8
    };
    let seam = [mix(16), mix(8), mix(0)];
    RenderCell {
        ch: ' ',
        fg: seam,
        bg: seam,
        wide: false,
        emoji_presentation: false,
        text_presentation: false,
        bold: false,
        italic: false,
        underline: aterm_core::terminal::UnderlineStyle::None,
        strikethrough: false,
        overline: false,
        underline_color: None,
        overline_color: None,
        script: aterm_core::terminal::Script::Normal,
    }
}

/// Which side of the active pane a divider run marks. Named for the pane's side,
/// not the divider's: `Left` is the divider column immediately left of the pane,
/// and its stripe hugs that column's right edge — the edge touching the pane.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum ActivePaneEdge {
    Left,
    Right,
    Top,
    Bottom,
}

/// The ink of the active pane's edge stripe: the theme's own foreground.
///
/// It is the one colour a theme guarantees is legible against its background,
/// and the seam it sits on is exactly halfway between the two, so the stripe
/// always has half the theme's own text contrast behind it. Deliberately not the
/// cursor or selection colour: a theme is free to make those loud, and this line
/// is chrome — it must never be the brightest thing on the screen.
fn active_pane_edge_ink(theme: Theme) -> [u8; 3] {
    [
        ((theme.fg >> 16) & 0xff) as u8,
        ((theme.fg >> 8) & 0xff) as u8,
        (theme.fg & 0xff) as u8,
    ]
}

/// One divider cell carrying the active pane's edge stripe: the seam cell with
/// a one-eighth block element filling the sliver touching the pane.
///
/// The four glyphs (U+2580–259F, synthesized by `procedural.rs`) are anchored
/// to the edge they name and all keep the seam as background and the ink as
/// foreground, so `minimum_contrast` treats all four sides alike. Cells are
/// about twice as tall as wide, so top/bottom stripes are about twice as thick
/// as left/right; an eighth is the finest block fraction.
pub(crate) fn active_pane_edge_cell(theme: Theme, edge: ActivePaneEdge) -> RenderCell {
    let seam = divider_cell(theme);
    RenderCell {
        ch: match edge {
            // The divider above the pane, inked along its bottom edge.
            ActivePaneEdge::Top => '▁',
            // …below the pane, inked along its top edge.
            ActivePaneEdge::Bottom => '▔',
            // …left of the pane, inked along its right edge.
            //
            // The vertical arms take a HALF block where the horizontal arms take
            // an eighth, because a cell is far taller than it is wide: an eighth
            // of the height is a 2px rule, but an eighth of the width is a single
            // physical pixel at the default 9x17 cell — indistinguishable from
            // the seam's own antialiasing, which is not a mark at all. Unicode
            // offers no quarter on the right or upper sides, so the half is the
            // next fraction that exists on both.
            ActivePaneEdge::Left => '▐',
            // …right of the pane, inked along its left edge.
            ActivePaneEdge::Right => '▌',
        },
        fg: active_pane_edge_ink(theme),
        ..seam
    }
}

/// The pane that takes keystrokes, as a rectangle of composite cells.
///
/// The mark lives in the divider gap because dimming unfocused panes cannot be
/// applied whole: colour emoji, inline image placements and sparkle-word ink
/// ignore `RenderCell::fg`. The gap holds no content, so what the panes
/// contain cannot change what the mark says.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct ActivePaneMark {
    pub(crate) row: usize,
    pub(crate) col: usize,
    pub(crate) rows: usize,
    pub(crate) cols: usize,
}

impl ActivePaneMark {
    /// The mark a composed frame carries, or `None` for a frame that marks no
    /// pane.
    ///
    /// Two windows can show a split at once and only one of them has the
    /// keyboard, so an unfocused window marks nothing: the honest answer to
    /// "which pane takes my keystrokes" there is "none of them". A single-pane
    /// window needs no gate of its own — it owns every cell of the composite, so
    /// the four lines just outside its rectangle fall off the grid and nothing is
    /// stamped.
    pub(crate) fn resolve(
        enabled: bool,
        window_focused: bool,
        rect: (usize, usize, usize, usize),
    ) -> Option<Self> {
        let (row, col, rows, cols) = rect;
        (enabled && window_focused && rows > 0 && cols > 0).then_some(ActivePaneMark {
            row,
            col,
            rows,
            cols,
        })
    }

    /// This frame's term for [`crate::RepaintKey`]. `0` for a frame that marks no
    /// pane, which is the idle invariant every sibling term holds: a single-pane,
    /// unfocused or disabled key stays byte-identical to the pre-mark shape. A
    /// marked frame's hash is forced ODD so it can never collide with that
    /// sentinel (the `native_fp | 1` idiom).
    pub(crate) fn key_term(mark: Option<Self>) -> u64 {
        use std::hash::{Hash, Hasher};

        let Some(mark) = mark else {
            return 0;
        };
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        (mark.row, mark.col, mark.rows, mark.cols).hash(&mut hasher);
        hasher.finish() | 1
    }
}

/// Stamp the active pane's edges into the divider cells bordering it.
///
/// Touches only cells that belong to no pane: [`fill_divider_grid_cells`] seeds
/// the whole composite with seam cells and every pane's blit then overwrites its
/// own rectangle, so the four lines just outside `mark` are divider gaps by
/// construction. Running here — before the blits — is what makes a disagreement
/// between this rectangle and the layout show no mark instead of eating a pane's
/// text: the blit wins any cell both of them claim.
///
/// The top and bottom runs reach one cell past each side so they MEET the left
/// and right runs at the pane's corners; without that the ring has a notch at
/// every corner, which reads as two unrelated lines rather than one frame.
fn mark_active_pane_edges(
    dst: &mut RenderInput,
    rows: usize,
    cols: usize,
    theme: Theme,
    mark: ActivePaneMark,
) {
    let row_end = mark.row.saturating_add(mark.rows).min(rows);
    let col_end = mark.col.saturating_add(mark.cols).min(cols);
    let across = mark.col.saturating_sub(1)..col_end.saturating_add(1).min(cols);
    let stamp_row = |dst: &mut RenderInput, r: usize, edge| {
        let cell = active_pane_edge_cell(theme, edge);
        if let Some(dst_row) = dst.cells.get_mut(r) {
            let span = across.start.min(dst_row.len())..across.end.min(dst_row.len());
            dst_row[span].fill(cell);
        }
    };
    if let Some(above) = mark.row.checked_sub(1) {
        stamp_row(dst, above, ActivePaneEdge::Top);
    }
    if mark.row.saturating_add(mark.rows) < rows {
        stamp_row(dst, row_end, ActivePaneEdge::Bottom);
    }
    let stamp_col = |dst: &mut RenderInput, c: usize, edge| {
        let cell = active_pane_edge_cell(theme, edge);
        for r in mark.row..row_end {
            if let Some(slot) = dst.cells.get_mut(r).and_then(|row| row.get_mut(c)) {
                *slot = cell;
            }
        }
    };
    if let Some(left) = mark.col.checked_sub(1) {
        stamp_col(dst, left, ActivePaneEdge::Left);
    }
    if mark.col.saturating_add(mark.cols) < cols {
        stamp_col(dst, col_end, ActivePaneEdge::Right);
    }
}

