#[cfg(test)]
mod overlay_card_theme_tests {
    use crate::{App, WindowId};

    #[test]
    fn overlay_card_tracks_live_background_and_theme_fallback() {
        let mut app = App::headless_for_test();
        app.theme.bg = 0x00FF_FFFF; // a light user theme
        let wid0 = WindowId(0);
        if let Some(ws) = app.windows.get_mut(&wid0) {
            ws.input_scratch.default_bg = 0x0012_3456;
        }
        assert_eq!(
            app.overlay_card_theme(wid0).bg,
            0x0012_3456,
            "a terminal window's overlay still tracks the live OSC-11 bg"
        );
        // An unset live background never overrides the theme.
        if let Some(ws) = app.windows.get_mut(&wid0) {
            ws.input_scratch.default_bg = aterm_core::render::COLOR_UNSET;
        }
        assert_eq!(app.overlay_card_theme(wid0).bg, 0x00FF_FFFF);
    }
}

#[cfg(test)]
mod prediction_ghost_tests {
    use super::{paint_prediction_ghosts, terminal_blank_cell, with_borrowed_prediction_overlay};
    use crate::predict::{PredictMode, Prediction, Predictor};
    use aterm_core::terminal::{RenderCell, Terminal};
    use aterm_render::RenderInput;
    use std::time::Instant;

    fn blank() -> RenderCell {
        RenderCell {
            ch: ' ',
            fg: [200, 200, 200],
            bg: [0, 0, 0],
            wide: false,
            emoji_presentation: false,
            text_presentation: false,
            bold: false,
            italic: false,
            underline: aterm_core::terminal::UnderlineStyle::None,
            strikethrough: false,
            overline: false,
            underline_color: None,
            overline_color: None,
            script: aterm_core::terminal::Script::Normal,
        }
    }

    fn scratch(rows: usize) -> RenderInput {
        let mut s = RenderInput::empty();
        s.cells = vec![Vec::new(); rows];
        s
    }

    /// A guess past a trimmed row's end extends it with pad cells, sets the glyph,
    /// and dims the fg toward the cell's bg (tentative, legible on any theme).
    #[test]
    fn ghost_extends_row_and_dims() {
        let mut s = scratch(2);
        let preds = [Prediction::test_at(1, 3, 'x')];
        assert!(paint_prediction_ghosts(&mut s, &preds, 10, blank()));
        assert_eq!(s.cells[1].len(), 4, "row extended to hold the ghost");
        let c = &s.cells[1][3];
        assert_eq!(c.ch, 'x');
        assert_eq!(c.fg, [100, 100, 100], "fg dimmed halfway to bg");
        assert!(!c.bold && !c.wide, "inherited SGR/geometry dropped");
    }

    /// Sparse tail padding represents implicit empty terminal cells. It must use
    /// the resolved terminal blank, not clone the final materialized cell's SGR
    /// background (which creates the same broad colored-band artifact as a
    /// divider sentinel leaking through a ragged row).
    #[test]
    fn ghost_sparse_padding_uses_terminal_blank_not_last_sgr() {
        let mut s = scratch(1);
        let mut styled = blank();
        styled.ch = '!';
        styled.bg = [180, 20, 30];
        styled.fg = [255, 255, 255];
        styled.bold = true;
        s.cells[0].push(styled);
        let terminal_blank = blank();

        assert!(paint_prediction_ghosts(
            &mut s,
            &[Prediction::test_at(0, 3, 'x')],
            5,
            terminal_blank,
        ));

        assert_eq!(s.cells[0][0], styled, "materialized SGR cell is preserved");
        assert_eq!(
            s.cells[0][1], terminal_blank,
            "first implicit tail cell uses the terminal blank"
        );
        assert_eq!(
            s.cells[0][2], terminal_blank,
            "all intervening implicit cells use the terminal blank"
        );
        assert_eq!(s.cells[0][3].bg, terminal_blank.bg);
        assert!(!s.cells[0][3].bold);
    }

    #[test]
    fn ghost_sparse_padding_tracks_live_terminal_defaults() {
        let mut term = Terminal::new(1, 5);
        term.process(b"\x1b]10;rgb:11/22/33\x07");
        term.process(b"\x1b]11;rgb:44/55/66\x07");
        term.process(b"\x1b[?5h");
        let live_blank = terminal_blank_cell(&term);
        let mut s = scratch(1);

        assert!(paint_prediction_ghosts(
            &mut s,
            &[Prediction::test_at(0, 3, 'x')],
            5,
            live_blank,
        ));
        assert_eq!(s.cells[0][1].fg, [0x44, 0x55, 0x66]);
        assert_eq!(
            s.cells[0][1].bg,
            [0x11, 0x22, 0x33],
            "DECSCNM-resolved live defaults, not the static app theme"
        );
        assert_eq!(s.cells[0][3].bg, live_blank.bg);
    }

    /// A guess at or past `cols` is DROPPED: on the composed path the pane blit
    /// does not clip to the pane's sub-rect, so an unclipped ghost would bleed
    /// into the neighboring pane. Out-of-range rows are ignored too.
    #[test]
    fn ghost_clips_to_pane_rect() {
        let mut s = scratch(2);
        let preds = [
            Prediction::test_at(0, 5, 'a'), // at cols → clipped
            Prediction::test_at(0, 9, 'b'), // past cols → clipped
            Prediction::test_at(7, 0, 'c'), // past rows → ignored
        ];
        assert!(
            !paint_prediction_ghosts(&mut s, &preds, 5, blank()),
            "nothing painted when everything clips"
        );
        assert!(s.cells[0].is_empty(), "clipped ghosts never extend the row");
        let ok = [Prediction::test_at(0, 4, 'd')]; // last in-rect column paints
        assert!(paint_prediction_ghosts(&mut s, &ok, 5, blank()));
        assert_eq!(s.cells[0][4].ch, 'd');
    }

    #[test]
    fn predictor_overlay_is_borrowed_and_paints_byte_identically() {
        let now = Instant::now();
        let mut predictor = Predictor::new(PredictMode::Always);
        assert!(predictor.predict_char('a', (0, 0), 5, now));
        assert!(predictor.predict_char('b', (0, 0), 5, now));

        let mut actual = scratch(1);
        actual.cells[0] = vec![blank(); 5];
        let mut expected = actual.clone();
        assert!(paint_prediction_ghosts(
            &mut expected,
            &[
                Prediction::test_at(0, 0, 'a'),
                Prediction::test_at(0, 1, 'b'),
            ],
            5,
            blank(),
        ));

        let source_allocation = predictor.overlay(now).as_ptr();
        let row_allocation = actual.cells[0].as_ptr();
        let row_capacity = actual.cells[0].capacity();
        let (borrowed_allocation, painted, last) =
            with_borrowed_prediction_overlay(&mut predictor, now, |predictions| {
                (
                    predictions.as_ptr(),
                    paint_prediction_ghosts(&mut actual, predictions, 5, blank()),
                    predictions.last().map(|p| (p.row, p.col)),
                )
            });

        assert!(painted);
        assert_eq!(last, Some((0, 1)));
        assert_eq!(
            actual.cells, expected.cells,
            "borrowed and copied overlays agree"
        );
        assert_eq!(
            borrowed_allocation, source_allocation,
            "the painter receives Predictor's resident slice, not a copied Vec",
        );
        assert_eq!(actual.cells[0].as_ptr(), row_allocation);
        assert_eq!(actual.cells[0].capacity(), row_capacity);
    }
}

#[cfg(test)]
#[path = "app_render_comet_trail_tests.rs"]
mod comet_trail_tests;

#[cfg(test)]
mod gpu_backpressure_tests {
    use super::gpu_backpressure_excess_ns;
    use std::time::Duration;

    /// Healthy display pacing must contribute exactly zero to the load-shed EMA —
    /// that invariant is why swapchain acquire was excluded from the causal cost in
    /// the first place, and breaking it would shed every effect on an idle machine
    /// that simply presents at the refresh rate.
    #[test]
    fn healthy_pacing_charges_nothing() {
        let fi = Duration::from_micros(8333); // 120 Hz
        assert_eq!(gpu_backpressure_excess_ns(0, fi), 0);
        assert_eq!(gpu_backpressure_excess_ns(1_000_000, fi), 0); // 1 ms wait
        // A wait of exactly one full refresh is still pacing, not back-pressure.
        assert_eq!(gpu_backpressure_excess_ns(8_333_000, fi), 0);
    }

    /// Past a full refresh the drawable pool is exhausted because the GPU has not
    /// finished prior frames — genuine back-pressure, and the only condition under
    /// which shedding the (pure-GPU) bloom and shimmer passes can help.
    #[test]
    fn exhausted_pool_charges_only_the_excess() {
        let fi = Duration::from_micros(8333);
        assert_eq!(gpu_backpressure_excess_ns(10_333_000, fi), 2_000_000);
        assert_eq!(gpu_backpressure_excess_ns(25_000_000, fi), 16_667_000);
        // At 60 Hz the same absolute wait is proportionally less alarming.
        let fi60 = Duration::from_micros(16667);
        assert_eq!(gpu_backpressure_excess_ns(25_000_000, fi60), 8_333_000);
    }
}

#[cfg(test)]
#[path = "app_render_motion_policy_tests.rs"]
mod motion_policy_tests;

/// Reuse the two cursor-neighbor rows already captured under this terminal
/// lock when Rainbow Kitty's content witness asks for either of them. A fresh
/// read is needed only for a different ribbon row. The caller must feed rows
/// from the same terminal generation as `above` and `below`.
pub(crate) fn captured_witness_neighbor<'a>(
    row: u16,
    caret_row: u16,
    above: Option<&'a [char]>,
    below: Option<&'a [char]>,
) -> Option<&'a [char]> {
    if caret_row.checked_sub(1) == Some(row) {
        return above;
    }
    if caret_row.checked_add(1) == Some(row) {
        return below;
    }
    None
}

/// Whether a composed frame must take a second terminal lock for a row newly
/// requested after scroll reconciliation. Ordinarily every requested far row
/// is already in the exact extraction sample and this returns false.
fn needs_fresh_witness_read(
    rows: &[u16],
    caret_row: u16,
    pane_row: usize,
    pane_rows: usize,
    above: Option<&[char]>,
    below: Option<&[char]>,
    captured: &ComposedWitnessRows,
) -> bool {
    rows.iter().any(|&row| {
        row != caret_row
            && usize::from(row)
                .checked_sub(pane_row)
                .is_some_and(|local| local < pane_rows)
            && captured_witness_neighbor(row, caret_row, above, below).is_none()
            && captured.get(row).is_none()
    })
}

#[cfg(test)]
mod witness_row_capture_tests {
    use super::{ComposedWitnessRows, captured_witness_neighbor, needs_fresh_witness_read};

    #[test]
    fn adjacent_ribbon_rows_reuse_captured_glyphs_without_a_second_grid_read() {
        let above = ['═', 'A'];
        let below = [' ', 'B'];
        for (row, want) in [(4, &above[..]), (6, &below[..])] {
            assert_eq!(
                captured_witness_neighbor(row, 5, Some(&above), Some(&below)),
                Some(want),
                "the witness reuses the exact captured glyphs"
            );
        }
        assert_eq!(
            captured_witness_neighbor(8, 5, Some(&above), Some(&below)),
            None
        );
        assert_eq!(captured_witness_neighbor(4, 5, None, Some(&below)), None);
    }

    #[test]
    fn composed_neighbor_witnesses_skip_the_second_terminal_lock() {
        let above = ['A'];
        let below = ['B'];
        let caret_row = 13;
        let pane_row = 12;
        let pane_rows = 4;
        assert!(
            !needs_fresh_witness_read(
                &[12, 13, 14],
                caret_row,
                pane_row,
                pane_rows,
                Some(&above),
                Some(&below),
                &ComposedWitnessRows::default(),
            ),
            "the exact captured trio needs no second lock"
        );
        assert!(needs_fresh_witness_read(
            &[12, 13, 14, 15],
            caret_row,
            pane_row,
            pane_rows,
            Some(&above),
            Some(&below),
            &ComposedWitnessRows::default(),
        ));
        assert!(needs_fresh_witness_read(
            &[12, 13, 14],
            caret_row,
            pane_row,
            pane_rows,
            None,
            Some(&below),
            &ComposedWitnessRows::default(),
        ));
        assert!(
            !needs_fresh_witness_read(
                &[11, 12, 13, 14, 16],
                caret_row,
                pane_row,
                pane_rows,
                Some(&above),
                Some(&below),
                &ComposedWitnessRows::default(),
            ),
            "out-of-pane rows need neither a lock nor a witness"
        );
    }
}

/// One frame's terminal-state snapshot for [`App::cursor_frame`] — the exact
/// per-frame inputs `redraw_window`'s frame hold reads for the cursor-effect pass,
/// snapshotted under the caller's Terminal lock (cursor + colours stay one
/// coherent observation), plus the animation clock and the window's cell grid.
pub(crate) struct CursorFxInputs {
    /// The animation clock (one `Instant` per redraw / capture).
    pub now: Instant,
    /// Window grid rows (terminal content — no tab-strip rows).
    pub rows: usize,
    /// Window grid cols.
    pub cols: usize,
    /// The cursor cell — the engines' move sensor. `None` on a scrolled-back
    /// viewport; the composed, focus and headless paths also give `None` for
    /// a DECTCEM-hidden caret, while the single-pane present hands it over
    /// (a hidden cursor is still a caret, for the pet) and says so in
    /// [`Self::cursor_visible`]. The motion engines read it through
    /// [`aterm_effects::host::motion_caret`], which withholds a hidden one
    /// on a frame the program has not finished or on an empty row
    /// ([`Self::hidden_withheld`]).
    pub cur: Option<(u16, u16)>,
    /// Whether this frame presents the active grid rather than retained
    /// scrollback. Cursor-owned geometry is invalid in history coordinates and
    /// is retired immediately; DECTCEM hiding on the live grid stays distinct.
    pub live_viewport: bool,
    /// Raw cursor visibility (DECTCEM): feeds the `ATERM_TRACE_SPAWN`
    /// diagnostic and the glow engine's `observe_caret_drawn`.
    pub cursor_visible: bool,
    /// [`aterm_effects::host::hidden_caret_withheld`]: a hidden caret on a
    /// row whose every cell is empty is no caret either (Claude Code's question dialog
    /// parks it on the blank bottom row for its last option). Otherwise
    /// [`aterm_core::terminal::Terminal::sync_frame_unfinished`], read under
    /// the same lock as [`Self::cur`]: the program's DEC-2026 bracket is
    /// still open by its OWN account and has been written into. A frame that
    /// reaches the tick with it set shows the program's frame half-written:
    /// the SYNC-1 hold ran out at `SYNC_HOLD_CAP` with the mode still set, or
    /// the terminal's `sync_timeout_ms` force-cleared the mode mid-frame (no
    /// hold at all then). A hidden cursor on it is the program's write
    /// position, which [`aterm_effects::host::motion_caret`] withholds from
    /// every motion engine. That half is NOT the mode level: a present of a bracket
    /// closed and reopened clean (`sync_frame_hold`'s close+reopen release)
    /// reads `false`, because that grid is the finished frame, and a
    /// timed-out bracket reads `true`, because it is not. The pet reads
    /// [`Self::cur`] beside this struct, not through it, with the unfinished
    /// half of this fact beside it (`TerminalFacts::frame_unfinished`).
    pub hidden_withheld: bool,
    /// Live cursor shape (the rainbow cursor requires a BLOCK).
    pub cursor_style: CursorStyle,
    /// This window's GUI blink phase — the rainbow twinkle's flip source (its
    /// edges become star flares once the rainbow-kitty style pins the shape steady).
    pub blink_phase: bool,
    /// Effective live cursor colour: OSC 12 when set, otherwise the live OSC 10
    /// foreground. Rewires the glow/trail colours exactly like the cursor body.
    pub live_cursor_rgb: [u8; 3],
    /// Whether `live_cursor_rgb` was pinned — asked for by someone — rather
    /// than being the theme's own seed. True when the user wrote a
    /// `cursor_color` into the config, or a program sent a live OSC 12
    /// (`Terminal::cursor_color_recoloured`). The rainbow and phaser blocks
    /// wear a pinned colour and build from white otherwise; the value alone
    /// cannot say which, because the theme seeds the terminal's slot and a
    /// seeded green and a requested green arrive as the same three bytes.
    pub cursor_color_pinned: bool,
    /// Live default background (DECSCNM-folded) — the rainbow's dark-theme input.
    pub default_bg: u32,
    /// Row probe `(row, caret, trust)` for this frame — the chars ride in
    /// the window's `poof_row_buf`, captured under the same term lock as the
    /// cursor sample (row/caret in the same coordinate space as `cur`).
    /// `None` when the viewport is scrolled back, history shifted this frame,
    /// or the caller doesn't probe (headless without a capture) — the engine
    /// then keeps its previous probe and the poof detector idles. The trust
    /// class ([`row_probe_trust`]) says which detector families may read it:
    /// a plain alt-screen frame (no repaint blink) ships `ContentOnly`, so
    /// the typed-echo confirm proof stays fed (the `no-row-probe` repair)
    /// while the kill/poof detector keeps refusing exactly what it always
    /// refused there.
    pub row_probe: Option<(u16, u16, aterm_effects::cursor_glow::ProbeTrust)>,
    /// Flanking-row presence as [`capture_cursor_neighbor_rows`] answered it
    /// under the same lock as `row_probe`: `false` for a grid edge, and for
    /// both rows on a frame v2 did not own (the capture skipped them). Every
    /// live caller supplies `Some`. `None` (the test sample's default, which
    /// feeds no probe) infers ordinary whole-grid edges from `row_probe`
    /// alone, and a caller that feeds a probe must not lean on it: inferred,
    /// an uncaptured row inside the grid reads as present, and the engine
    /// keeps the cleared buffer as a real blank row for the seam's content
    /// witnesses (Rainbow Kitty's first frame after it engages). Composed
    /// callers need it besides so an active rainbow pane edge is not
    /// mistaken for a real blank row merely because it lies inside the
    /// window.
    pub row_probe_neighbors: Option<(bool, bool)>,
    /// The live default FOREGROUND (`0x00RRGGBB`), the twin of `default_bg`.
    /// The cursor-effect layer anchors its fresh-typed glyph tint on it, and
    /// the pair must come from one observation or a DECSCNM-swapped frame gets
    /// a foreground from one side and a background from the other.
    pub default_fg: u32,
    /// The echo anchor (`Terminal::print_anchor`): where the most recent PTY
    /// print run ended, `(row, col, seq)` in the same window coordinates as
    /// `cur`, sampled under the same lock. Feeds the glow engine's hidden-caret
    /// lane; `None` (scrolled back, unwired caller) keeps the previous sample.
    pub print_anchor: Option<(u16, u16, u64)>,
    /// The glyph at that print run's last cell (`Terminal::print_anchor_glyph`),
    /// from the same lock hold and under the same live-viewport guard as
    /// `print_anchor` — no translation, it is a cell's content. The witness the
    /// engine's visible-parked lane reads to tell a key's echo from a status
    /// row's (zsh's i-search minibuffer ends on its fake cursor `_`, as far as
    /// two rows below the caret under a wrapped match). `None` means unknown:
    /// the engine then judges exactly as a host that never sampled it.
    pub print_anchor_glyph: Option<char>,
}

#[cfg(test)]
impl CursorFxInputs {
    /// A neutral frame for tests that drive [`App::cursor_frame`] without caring
    /// about the terminal's exact state. Adding a field to the struct? Give it
    /// a value here in the same edit; test fixtures build through this.
    pub(crate) fn sample_for_test(now: Instant) -> Self {
        Self {
            now,
            rows: 24,
            cols: 80,
            cur: Some((0, 0)),
            live_viewport: true,
            cursor_visible: true,
            hidden_withheld: false,
            cursor_style: CursorStyle::SteadyBlock,
            blink_phase: true,
            live_cursor_rgb: [255, 255, 255],
            // A bare test sample pins nothing: the caret builds from white.
            // A fixture modelling OSC 12 or a configured `cursor_color`
            // sets this `true` itself — that is what "pinned" means.
            cursor_color_pinned: false,
            default_bg: Theme::default().bg,
            row_probe: None,
            row_probe_neighbors: None,
            default_fg: Theme::default().fg,
            print_anchor: None,
            print_anchor_glyph: None,
        }
    }
}

